-- 00012_study_expansion.sql
-- Basketball IQ: 12 sections (8 new), 3 lessons each, 7 quiz questions per lesson
-- (252 questions). Run AFTER seed.sql. Safe to re-run.

-- study.sql
-- Basketball IQ study content expansion: 12 topics x 3 lessons, 7 quiz questions per lesson.
-- Safe to re-run: the constraint is dropped/re-added, topics skip existing slugs,
-- lessons skip existing titles, and quiz top-ups only run while a lesson has fewer than 7 questions.
-- Note: new lessons use youtube_video_id = 'placeholder'; the app links each lesson to a YouTube search by title.

-- =============================================================================
-- 1. ALLOWED STUDY CATEGORIES
-- =============================================================================
ALTER TABLE public.study_topics DROP CONSTRAINT IF EXISTS study_topics_category_check;
ALTER TABLE public.study_topics ADD CONSTRAINT study_topics_category_check CHECK (category IN (
  'shooting_mechanics', 'finishing', 'ball_handling', 'pick_and_roll', 'defense', 'spacing_and_movement',
  'transition', 'film_study', 'rebounding', 'post_play', 'game_situations', 'mental_game'
));

-- =============================================================================
-- 2. NEW STUDY TOPICS
-- =============================================================================
INSERT INTO public.study_topics (title, slug, description, category, icon_name, display_order, is_active) VALUES
('Ball Handling', 'ball-handling', 'Protect the ball under pressure, change pace and direction to beat defenders, and stay calm against traps.', 'ball_handling', 'Hand', 5, true),
('Spacing & Off-Ball Movement', 'spacing-off-ball', 'Learn where to stand, when to cut, and how to use off-ball screens so every drive and pass gets easier.', 'spacing_and_movement', 'Move', 6, true),
('Transition Offense & Defense', 'transition', 'Run the floor with purpose, turn numbers advantages into easy baskets, and sprint back to stop the break.', 'transition', 'FastForward', 7, true),
('Reading the Game & Film Study', 'film-study', 'Study your own game and your opponents, and learn to read the defense in real time.', 'film_study', 'Film', 8, true),
('Rebounding', 'rebounding', 'Box out on every shot, attack the offensive glass with smart angles, and finish defensive possessions as a team.', 'rebounding', 'ArrowUpFromLine', 9, true),
('Post Play', 'post-play', 'Establish position, score with core post moves and counters, and pass out of double teams.', 'post_play', 'Anchor', 10, true),
('Game Situations & Clock Management', 'game-situations', 'Manage the game clock, the shot clock, fouls, timeouts, and inbounds plays when the game is on the line.', 'game_situations', 'Timer', 11, true),
('Mental Game', 'mental-game', 'Build confidence, create a pre-shot routine, bounce back from mistakes, and use visualization to prepare.', 'mental_game', 'Brain', 12, true)
ON CONFLICT (slug) DO NOTHING;

-- =============================================================================
-- 3. LESSONS (inserted only if the title does not already exist for the topic)
--    and 4. QUIZ TOP-UPS for the original seed lessons
-- =============================================================================
DO $$
DECLARE
  v_shooting uuid;
  v_finishing uuid;
  v_pnr uuid;
  v_defense uuid;
  v_ball uuid;
  v_spacing uuid;
  v_transition uuid;
  v_film uuid;
  v_rebounding uuid;
  v_post uuid;
  v_situations uuid;
  v_mental uuid;
BEGIN
  SELECT id INTO v_shooting FROM public.study_topics WHERE slug = 'shooting-mechanics' LIMIT 1;
  SELECT id INTO v_finishing FROM public.study_topics WHERE slug = 'finishing-footwork' LIMIT 1;
  SELECT id INTO v_pnr FROM public.study_topics WHERE slug = 'pnr-reads' LIMIT 1;
  SELECT id INTO v_defense FROM public.study_topics WHERE slug = 'defense-rotations' LIMIT 1;
  SELECT id INTO v_ball FROM public.study_topics WHERE slug = 'ball-handling' LIMIT 1;
  SELECT id INTO v_spacing FROM public.study_topics WHERE slug = 'spacing-off-ball' LIMIT 1;
  SELECT id INTO v_transition FROM public.study_topics WHERE slug = 'transition' LIMIT 1;
  SELECT id INTO v_film FROM public.study_topics WHERE slug = 'film-study' LIMIT 1;
  SELECT id INTO v_rebounding FROM public.study_topics WHERE slug = 'rebounding' LIMIT 1;
  SELECT id INTO v_post FROM public.study_topics WHERE slug = 'post-play' LIMIT 1;
  SELECT id INTO v_situations FROM public.study_topics WHERE slug = 'game-situations' LIMIT 1;
  SELECT id INTO v_mental FROM public.study_topics WHERE slug = 'mental-game' LIMIT 1;

  -- ---------------------------------------------------------------------------
  -- Shooting Mechanics: top up the 2 original lessons, add lesson 3
  -- ---------------------------------------------------------------------------
  UPDATE public.study_items SET quiz_questions = '[
    {"question": "What is the primary mechanical purpose of dipping the basketball upon catch?", "options": ["To hide the ball from defenders", "To synchronize lower body dip with upward shot rhythm", "To add backspin", "To slow down the shot speed"], "correct_index": 1, "explanation": "Dipping the ball syncs the ball with hip flexion, allowing energy to travel upward without a power leak."},
    {"question": "What happens when a player pauses the ball at their forehead before jumping?", "options": ["The shot gains arc", "The shot loses lower-body kinetic energy, requiring excessive arm push", "The shot is less contestable", "Accuracy automatically increases"], "correct_index": 1, "explanation": "A hitch or pause breaks the kinetic chain, turning a fluid shot into an arm-dominant push."},
    {"question": "Where should most of the power in a jump shot come from?", "options": ["The legs and hips, transferring up through the core into the arm", "Mainly the shooting wrist", "The guide hand", "The shoulders shrugging upward"], "correct_index": 0, "explanation": "Power starts from the floor. The arm and wrist finish and aim the shot rather than generating most of its force."},
    {"question": "What is the best way to think about the dip?", "options": ["A big swooping motion down to the knees on every shot", "A pause so you can look at the defense", "Something every shooter should remove completely", "A short, consistent rhythm move that matches your knee bend"], "correct_index": 3, "explanation": "A small, repeatable dip matches your knee bend and keeps the shot connected. Oversized dips slow the release and are easier to contest."},
    {"question": "Decision point: You catch a pass already at chest height and a defender is closing out fast. How should you adjust your dip?", "options": ["Dip all the way to your knees for extra power", "Pass up the shot every time a defender closes out", "Shorten or skip the dip and rise straight up from the chest, keeping your legs connected", "Shoot using only your arms"], "correct_index": 2, "explanation": "When time is short, good shooters shrink or skip the dip but still use their legs, so the kinetic chain stays connected and the release stays quick."},
    {"question": "A shot that looks flat (low arc) usually comes from what?", "options": ["Pushing the ball forward from the forehead instead of rising up through the shot", "Too much knee bend", "Holding the follow-through", "Releasing the ball off the fingertips"], "correct_index": 0, "explanation": "Pausing and pushing forward sends the ball on a line. Rising up through the shot and releasing upward creates healthy arc."},
    {"question": "Which cue best supports a one-motion shot?", "options": ["Catch, stop, aim, then shoot", "Jump first, then start moving the ball", "Load the legs while keeping the ball still", "Up and through: the ball rises continuously with your legs into the release"], "correct_index": 3, "explanation": "A continuous up-and-through motion lets the energy from your legs flow straight into the release without a stop."}
  ]'::jsonb
  WHERE title = 'The One-Motion Shooting Dip & Kinetic Chain' AND jsonb_array_length(quiz_questions) < 7;

  UPDATE public.study_items SET quiz_questions = '[
    {"question": "If a right-handed shooter misses consistently left or right, what is the most common mechanical defect?", "options": ["Not enough knee bend", "Guide hand interference (thumb flick) or improper shoulder alignment", "Jumping too high", "Shooting too fast"], "correct_index": 1, "explanation": "Left/right misses are almost always caused by guide-hand pushing or misalignment of the shooting elbow/shoulder with the target."},
    {"question": "What is the job of the guide hand during the shot?", "options": ["To push the ball toward the rim", "To add sidespin", "To add power on long shots", "To balance and steady the ball, then come off without adding force"], "correct_index": 3, "explanation": "The guide hand is a passenger. It supports the ball until the release and should not push, flick, or steer it."},
    {"question": "Why do many shooters turn their feet and shoulders slightly (about 10 to 20 degrees) instead of standing fully square to the rim?", "options": ["It lines up the shooting eye, elbow, and hip with the rim naturally", "It makes the shot impossible to block", "It is required by the rules", "It adds extra backspin"], "correct_index": 0, "explanation": "A slight turn lets the shooting side sit under the ball so the elbow can stay in line with the target without strain."},
    {"question": "Where should the shooting elbow point at the set point?", "options": ["Out to the side, away from the body", "Down toward the floor", "Roughly toward the rim, under the ball", "Back toward the shooter"], "correct_index": 2, "explanation": "An elbow under the ball and pointed at the rim creates a straight line for the ball to travel on."},
    {"question": "Decision point: Watching film, you notice your left and right misses only increase when you shoot off the dribble. What should you try first?", "options": ["Switch to a different ball", "Stop shooting off the dribble completely", "Jump higher on every shot", "Gather the ball into the same shot pocket every time before rising"], "correct_index": 3, "explanation": "Off-the-dribble shots often start from a different spot. A consistent gather into your normal pocket keeps your alignment the same as your catch-and-shoot."},
    {"question": "What does a relaxed follow-through, with your fingers pointing at the rim and your wrist bent, usually tell you?", "options": ["The shot was definitely going in", "The ball came off your fingertips straight, with backspin", "The guide hand did most of the work", "You shot the ball too hard"], "correct_index": 1, "explanation": "A clean follow-through shows the ball rolled off your index and middle fingers last, which produces straight backspin."},
    {"question": "What is the shot pocket?", "options": ["The spot at the top of the key", "A pocket on your shorts", "The consistent spot, around your waist to chest on your shooting side, where your shot starts", "The space behind your head"], "correct_index": 2, "explanation": "Starting from the same pocket every time makes your shot repeatable, whether you are catching or coming off the dribble."}
  ]'::jsonb
  WHERE title = 'Shot Pocket Alignment & Guide Hand Discipline' AND jsonb_array_length(quiz_questions) < 7;

  IF v_shooting IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_shooting AND title = 'Shot Prep Footwork: The Hop vs. the 1-2 Step') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_shooting, 'Shot Prep Footwork: The Hop vs. the 1-2 Step',
      'Learn how to be shot-ready before the catch, when to use a hop or a 1-2 step, and how to square up to the rim while on the move.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Be loaded before the ball arrives: knees bent, hands up as a target, feet ready to step into the shot', 'The hop lands both feet together and keeps you balanced with options; the 1-2 step (inside foot first) turns you into the shot when moving', 'Rhythm beats speed: a balanced, on-time shot is quicker and more accurate than a rushed one'],
      'Think about your catch-and-shoot attempts from your last game or session. Were you ready before the catch, or did you have to gather yourself after? Which footwork felt most natural, and which will you practise this week?',
      '[
        {"question": "What does it mean to be shot-ready before the catch?", "options": ["Standing straight up so you can see the whole floor", "Calling loudly for the ball", "Having your knees bent, hands up as a target, and feet ready to step into the shot", "Holding the follow-through from your last shot"], "correct_index": 2, "explanation": "Being loaded before the ball arrives removes the extra gather and speeds up your release without rushing your mechanics."},
        {"question": "Coming off a screen toward the ball, which foot usually lands first in a 1-2 step so you can turn into the shot?", "options": ["The inside foot (the one closer to the basket), so your hips can turn toward the rim", "The outside foot, every time", "Whichever foot is stronger", "Neither, because you must always jump-stop"], "correct_index": 0, "explanation": "Landing inside foot first lets your hips rotate naturally so you are squared to the rim when the second foot lands."},
        {"question": "Decision point: You are spotted up in the corner and the ball is swung to you, but the pass is a little off target to one side. What is the best footwork choice?", "options": ["Catch it flat-footed and shoot immediately without adjusting", "Put it on the floor straight away, no matter what", "Call a timeout", "Use a quick hop into the catch to realign your feet under you before rising"], "correct_index": 3, "explanation": "A hop lets you land both feet together, re-square to the rim, and keep your rhythm even when the pass pulls you off line."},
        {"question": "What is one advantage of the hop (both feet landing together) on the catch?", "options": ["It always makes the shot longer", "You have not chosen a pivot foot yet, so you can shoot or drive either direction", "It is the only legal way to catch the ball", "It makes the shot slower but more accurate"], "correct_index": 1, "explanation": "Landing on both feet at once keeps your pivot foot options open, so you can attack either way if the defender closes out hard."},
        {"question": "Decision point: Late in a long practice, your jumpers keep falling short. What is the best adjustment?", "options": ["Focus on bending your knees and using your legs, since tired legs usually cause short misses", "Push harder with your arms", "Switch to a different ball", "Shoot with a flatter arc"], "correct_index": 0, "explanation": "Short misses usually mean your legs are not contributing. Consciously loading your legs fixes depth better than pushing with your arms."},
        {"question": "Decision point: You catch on the wing and your defender is sprinting at you with high hands, already at your chest. You are a capable shooter. What is the best play?", "options": ["Shoot over them anyway", "Use a shot fake or rip-and-go drive past the out-of-control closeout", "Hold the ball and wait for the defender to back off", "Pass back to the player who gave you the ball, every time"], "correct_index": 1, "explanation": "A defender flying at you is off balance. A shot fake or immediate attack turns their momentum against them and creates a better shot."},
        {"question": "Why do coaches say rhythm beats speed on catch-and-shoot jumpers?", "options": ["Slow shots always go in", "Fast shots are against the rules", "A balanced, connected motion is quicker and more consistent than a rushed one", "Rhythm only matters on free throws"], "correct_index": 2, "explanation": "Rushing breaks your mechanics. A connected, repeatable motion is both quick and accurate."}
      ]'::jsonb, 3);
  END IF;

  -- ---------------------------------------------------------------------------
  -- Finishing Footwork: top up the original lesson, add lessons 2 and 3
  -- ---------------------------------------------------------------------------
  UPDATE public.study_items SET quiz_questions = '[
    {"question": "What is the primary goal of taking a veer step toward a trailing shot blocker?", "options": ["To draw an offensive foul", "To initiate contact on your terms and nullify their vertical jump", "To pass out to the corner", "To slow down the play"], "correct_index": 1, "explanation": "Veering into the defender takes away their runway and jumping space, leaving you with an uncontested touch finish."},
    {"question": "When should the veer step happen?", "options": ["On your last step before take-off, after reading where the help defender is coming from", "After you have already jumped", "Only on fast breaks", "At half court"], "correct_index": 0, "explanation": "The veer is a last-step angle adjustment. You read the rim protector, then angle into their path before you leave the floor."},
    {"question": "Which part of your body should absorb contact on a veer finish?", "options": ["Your shooting hand", "Your head", "Your knees", "Your chest and shoulder, with your core braced"], "correct_index": 3, "explanation": "Leading with a braced chest and shoulder lets you absorb the bump, keep your balance, and still finish with a free hand."},
    {"question": "Decision point: You drive baseline and a help defender slides over from the middle of the lane to block your layup. What is the best finish?", "options": ["Fade away from the defender with a falling-away shot", "Stop and hold the ball", "Veer into their body and finish high off the glass with the hand farthest from them", "Pass back out to half court"], "correct_index": 2, "explanation": "Veering into the helper takes away their jump, and finishing with the far hand keeps the ball away from their reach."},
    {"question": "Why is fading away from a shot blocker often worse than veering into them?", "options": ["Fading makes your shot harder and gives the blocker free space to jump and reach", "Fading away is always a foul", "Veering is always an offensive foul", "There is no difference"], "correct_index": 0, "explanation": "When you drift away, the blocker gets a clean runway to jump. Taking their space with a veer removes that runway."},
    {"question": "What should your finishing hand do after you absorb contact?", "options": ["Drop to your waist", "Throw the ball hard at the rim", "Grab the defender", "Extend high and away from the defender, using the glass when possible"], "correct_index": 3, "explanation": "Extending high and away from the defender, with a soft touch off the glass, keeps the ball out of their reach."},
    {"question": "Decision point: You veer into the rim protector, but they stay straight up with their arms vertical and do not jump. What is the smartest option?", "options": ["Jump into them harder to try to force a foul", "Use a pump fake or up-and-under, or kick it to the open teammate whose defender helped", "Throw the ball at the rim without looking", "Take extra steps to get around them"], "correct_index": 1, "explanation": "A defender who stays vertical is defending well. Make them move with a fake, or punish the help by finding the teammate they left open."}
  ]'::jsonb
  WHERE title = 'The Veer Finish: Contact Absorption and Rim Protection' AND jsonb_array_length(quiz_questions) < 7;

  IF v_finishing IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_finishing AND title = 'The Euro Step & Change-of-Direction Finishes') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_finishing, 'The Euro Step & Change-of-Direction Finishes',
      'Use a long lateral second step to get around a defender who commits to your driving line, and learn when the euro step is the right tool and when it is not.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Sell the first step hard so the defender commits to that line', 'The second step goes long and lateral, with the ball protected on the side away from the defender', 'Euro step when a defender steps into your path; go straight up or veer when they are trailing'],
      'Think about your last few drives to the rim in a game or scrimmage. Did any defender step into your path? Would a euro step have worked, and which direction are you more comfortable going?',
      '[
        {"question": "What is the key read that tells you to use a euro step?", "options": ["A defender steps into your driving line and commits to it", "Your defender is trailing behind you", "Nobody is in the paint", "The shot clock is full"], "correct_index": 0, "explanation": "The euro step punishes a defender who commits to one path. If nobody is in your way, go straight to the rim."},
        {"question": "How should the second step of a euro step be taken?", "options": ["Short and straight ahead", "Backward, away from the rim", "Crossing over in front of your first foot", "Long and lateral, away from the defender, with the ball protected on that side"], "correct_index": 3, "explanation": "A long lateral second step creates separation from the defender, and carrying the ball on the far side keeps it safe."},
        {"question": "Where should the ball be as you move from the first step to the second?", "options": ["Held out in one hand toward the defender", "Dribbled one more time", "Moved across your body with two hands, kept tight and away from the defender''s reach", "Held above your head the whole time"], "correct_index": 2, "explanation": "Moving the ball with two hands, tight to your body, lets it travel with your step without being exposed to a swipe."},
        {"question": "Decision point: In transition, the only defender back is backpedaling in front of you and sliding hard toward your right side. What is the best finish?", "options": ["Go straight into the defender''s chest on the right side", "Pick up the ball and pivot in place", "Sell the right side, then take a long euro step to the left and finish", "Throw the ball off the backboard to yourself"], "correct_index": 2, "explanation": "The defender has committed to your right. A euro step to the left uses their commitment against them and opens a clear finish."},
        {"question": "Decision point: You beat your defender on a drive, they are now trailing behind you, and nobody is in front of you. Should you euro step?", "options": ["Yes, always euro step on layups", "No, go straight up quickly; a euro step would slow you down and let the trailing defender recover", "Stop and pump fake first", "Yes, but only toward your weaker hand"], "correct_index": 1, "explanation": "The euro step is a counter for a defender in front of you. With a trailing defender, speed and a direct finish are your advantage."},
        {"question": "What is a hop-step (two-foot) finish?", "options": ["A jump stop onto both feet into a strong finish, giving balance and the option to fake or pivot in traffic", "A one-foot runner from far away", "A backward jump", "A dribble between the legs"], "correct_index": 0, "explanation": "Landing on two feet gives you balance and options: go up strong, pump fake, or pivot to pass."},
        {"question": "Decision point: You euro step past the first defender, but a second help defender is waiting under the rim. What is the best adjustment?", "options": ["Force the layup anyway", "Find the teammate whose defender helped, or pump fake to get the helper off their feet", "Dribble back out to half court", "Shoot a fadeaway three"], "correct_index": 1, "explanation": "A second helper means someone is open. Pass to that player, or use a fake to make the helper commit before you finish."}
      ]'::jsonb, 2);
  END IF;

  IF v_finishing IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_finishing AND title = 'Floaters, Runners & Touch Finishes Over Length') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_finishing, 'Floaters, Runners & Touch Finishes Over Length',
      'Learn when to release early over a set rim protector and how to control touch with high-arcing floaters and one-foot runners.',
      'placeholder', 'HoopIQ', 8,
      ARRAY['Release before the shot blocker can reach the ball: early and high', 'A floater comes off one or two feet with a soft, high arc so the ball drops down into the rim', 'Read the big: if they stay home at the rim, float it; if they step up, lob or dump it off'],
      'Recall a time in a recent game when you drove into a tall defender waiting at the rim. Did you finish, get blocked, or pass? Where on the floor could a floater have fit, and how many floaters did you practise this week?',
      '[
        {"question": "When is a floater usually the best option?", "options": ["When there is nobody between you and the rim", "From the three-point line", "Only on free throws", "When a shot blocker is set at the rim and you are roughly 6 to 12 feet away"], "correct_index": 3, "explanation": "The floater is built for the in-between zone, where a set rim protector would block a layup but you are too close for a normal jumper."},
        {"question": "What is the main advantage of a floater over a layup against a tall defender?", "options": ["You release the ball earlier and higher, before they can reach it", "It is worth more points", "It draws a foul every time", "It is easier to rebound your own miss"], "correct_index": 0, "explanation": "The early, high release beats the shot blocker''s timing and reach."},
        {"question": "What should the arc of a floater look like?", "options": ["Flat and hard off the backboard", "A line drive at the front of the rim", "High and soft, so the ball drops down into the rim", "As low as possible"], "correct_index": 2, "explanation": "A high, soft arc lets the ball clear long arms and drop gently into the rim, giving it a chance even if it is slightly off."},
        {"question": "Decision point: You come off a ball screen and drive. The opposing center steps up to the free-throw line area to stop you, leaving your rolling big behind them. What is the best read?", "options": ["Shoot a floater over the center", "Pass back out to the top", "Throw a lob or bounce pass to your rolling teammate behind the center", "Dribble backward and reset"], "correct_index": 2, "explanation": "If the big steps up to you, the rim is open behind them. The best shot is usually a dump-off or lob to your roller."},
        {"question": "What is a runner?", "options": ["A pass to a cutter", "A shot taken off one foot in stride while moving forward, released with a soft touch", "A three-pointer on the fast break", "A dunk"], "correct_index": 1, "explanation": "A runner is released in stride, using your forward momentum, so you do not have to stop and gather in traffic."},
        {"question": "How should players build floater touch?", "options": ["Only by trying it in games", "Only with their weaker hand", "By shooting it as hard as possible", "With lots of reps from different spots, off one and two feet, starting close and moving out"], "correct_index": 3, "explanation": "Touch comes from volume and variety. Build it up close first, then extend your range and add game-speed approaches."},
        {"question": "Decision point: You are in the lane about 8 feet out. The big is in drop coverage near the rim, and your defender is trailing on your back. What should you do?", "options": ["Keep driving into the big''s chest", "Rise into a floater before the big can close the gap", "Pick up the ball and look for a timeout", "Spin back toward half court"], "correct_index": 1, "explanation": "The big is staying home and your defender is behind you, so the space is yours. A quick floater uses it before either defender can recover."}
      ]'::jsonb, 3);
  END IF;

  -- ---------------------------------------------------------------------------
  -- Pick & Roll: top up the original lesson, add lessons 2 and 3
  -- ---------------------------------------------------------------------------
  UPDATE public.study_items SET quiz_questions = '[
    {"question": "When the opposing center is in deep drop coverage, what spacing advantage does the snake dribble provide?", "options": ["It forces an automatic foul", "It seals the trailing guard behind you and leaves the drop big in no-mans land", "It speeds up the possession", "It lets you reset to halfcourt"], "correct_index": 1, "explanation": "Snaking across the screen traps the recovering defender on your back, giving you a completely unimpeded floater or pocket pass."},
    {"question": "In drop coverage, where does the screener''s defender usually position?", "options": ["Back toward the paint, around the free-throw line or lower, to protect the rim", "Up at the level of the screen", "Trapping the ball handler", "Switching onto the ball handler"], "correct_index": 0, "explanation": "The drop big sits back to protect the rim and keep the roller in front, while the guard chases from behind."},
    {"question": "What shot does drop coverage usually give up?", "options": ["Dunks at the rim", "Corner threes by the screener", "Pull-up jumpers and floaters in the mid-range or behind the screen", "Nothing, it takes everything away"], "correct_index": 2, "explanation": "Drop coverage protects the rim and accepts that the ball handler may get pull-ups and mid-range looks."},
    {"question": "Decision point: The big drops deep and your defender goes under the screen. You are a confident shooter. What is the best read?", "options": ["Drive straight into the big", "Pass to the corner immediately", "Call for a re-screen with no plan", "Pull up for a jumper behind the screen, since both defenders are giving you space"], "correct_index": 3, "explanation": "When both defenders sag, the open shot is right behind the screen. Take it with confidence."},
    {"question": "What does the pocket pass exploit?", "options": ["A defender who is fouling", "The gap between the dropping big and the recovering guard, hitting the roller in stride", "Full-court pressure", "A switch onto a smaller player"], "correct_index": 1, "explanation": "The pocket pass threads the space between the two defenders as the roller dives, before the big can re-balance."},
    {"question": "Why should you avoid speeding up into a drop big?", "options": ["It is always a charge", "Your teammates cannot see you", "It wastes the shot clock", "You play into their hands, running into a set rim protector instead of making them commit"], "correct_index": 3, "explanation": "Drop coverage wants you to rush into the big. Changing pace and making the big commit gives you the advantage."},
    {"question": "Decision point: You snake the screen and the drop big finally steps up to your floater. Your roller is diving behind them. What is the read?", "options": ["Force the floater anyway", "Dribble out and reset", "Dump off or lob to the roller behind the big", "Shoot a step-back three"], "correct_index": 2, "explanation": "The big can not guard both of you. Once they step up to the ball, the roller behind them is open."}
  ]'::jsonb
  WHERE title = 'Reading Drop Coverage: Snaking & Mid-Range Floaters' AND jsonb_array_length(quiz_questions) < 7;

  IF v_pnr IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_pnr AND title = 'Beating Hedges & Blitzes: Playing 4-on-3') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_pnr, 'Beating Hedges & Blitzes: Playing 4-on-3',
      'When two defenders jump the ball handler, the offense has an advantage. Learn to retreat, split, or hit the short roll to punish aggressive coverage.',
      'placeholder', 'HoopIQ', 8,
      ARRAY['When two defenders go to the ball, someone is open: get the ball out quickly', 'Use a retreat dribble to create passing angles; do not pick up the ball inside the trap', 'The short roll is the release valve: the screener catches near the free-throw line and plays 4-on-3'],
      'Think about the last time you were trapped or hedged hard in a game. Did you pick up the ball, turn it over, or find the open player? What would you do differently now?',
      '[
        {"question": "What is a hedge in pick-and-roll defense?", "options": ["The screener''s defender sagging into the paint", "Both defenders switching", "The screener''s defender stepping out hard to slow the ball handler, then recovering to the screener", "The on-ball defender going under the screen"], "correct_index": 2, "explanation": "A hedge is a hard, temporary show to slow the ball handler and give the on-ball defender time to recover."},
        {"question": "What is a blitz (or trap) on a ball screen?", "options": ["Both defenders aggressively jump the ball handler to take the ball out of their hands", "A full-court press after a free throw", "A zone defense", "A defender switching onto the screener"], "correct_index": 0, "explanation": "A blitz sends two defenders at the ball, which means the other offensive players are playing 4-on-3."},
        {"question": "Decision point: You come off the screen and both defenders trap you. Your screener rolls toward the free-throw line with nobody guarding them. What is the best play?", "options": ["Try to split the trap with a hard dribble every time", "Pick up the ball and pivot", "Call for another screen", "Retreat a dribble to create space, then pass to the screener on the short roll"], "correct_index": 3, "explanation": "A retreat dribble creates the angle you need, and the short roller is the open player the trap left behind."},
        {"question": "Why is picking up your dribble inside a trap dangerous?", "options": ["It is a violation", "It lets the defenders smother you and removes your ability to create passing angles", "It forces you to shoot", "It stops the clock"], "correct_index": 1, "explanation": "Once you pick up the ball, the trappers can close in and take away your vision and passing lanes."},
        {"question": "When the screener catches on the short roll against a blitz, what situation do they usually face?", "options": ["1-on-3 against the whole defense", "A 4-on-3 advantage where they read the helper rotating from the weak side or corner", "A free shot with no defenders nearby", "An immediate double team"], "correct_index": 1, "explanation": "The short roller is the playmaker in a 4-on-3. They read the rotating defender and shoot, drive, or pass to whoever that helper left."},
        {"question": "Decision point: The big hedges high and wide, and a clear gap opens between the hedging big and your recovering defender. What is a good option?", "options": ["Split the gap between the two defenders and attack the paint before they recover", "Pass back to the corner immediately", "Stop and wait for the hedge to finish", "Turn your back and post up"], "correct_index": 0, "explanation": "If the two defenders leave a gap, splitting it puts you in the paint with the defense scrambling."},
        {"question": "When the screener''s defender hedges hard, what is the screener''s best timing?", "options": ["Pop to the corner right away every time", "Stand still and watch", "Roll or slip as soon as their defender commits to the ball handler", "Keep re-screening the same defender"], "correct_index": 2, "explanation": "The moment the screener''s defender commits to the ball, the screener is free. Rolling right then gives the ball handler an outlet."}
      ]'::jsonb, 2);
  END IF;

  IF v_pnr IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_pnr AND title = 'Attacking Switches & Slipping Screens') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_pnr, 'Attacking Switches & Slipping Screens',
      'Recognize switch-heavy defenses, punish mismatches, and use slips and ghost screens before the defense can get set.',
      'placeholder', 'HoopIQ', 8,
      ARRAY['Against a switch, attack the mismatch quickly, before the defense can help or switch back', 'If defenders switch early or show high, the screener should slip to the rim', 'Small defender on your big: seal and feed the post; big defender on your guard: attack in space'],
      'In your recent games, did the other team switch screens? Did your team take advantage of the mismatch, or did the possession stall? Name one action you can use next time.',
      '[
        {"question": "When the defense switches a ball screen, what should the offense look for first?", "options": ["A timeout", "A mismatch to attack quickly, before the defense can help or switch back", "A zone set", "A long three with plenty of time left"], "correct_index": 1, "explanation": "Switches create mismatches, but only briefly. Attack before the defense can send help or re-switch."},
        {"question": "Decision point: You are the ball handler. The big shows high on the screen and your roller slips to the rim before making contact. The weak-side defender is late to rotate. What is the best read?", "options": ["Keep dribbling to see what happens", "Pull up for a contested three over the big", "Reject the screen and drive the other way", "Hit the slipping screener with a quick pass for a layup"], "correct_index": 3, "explanation": "When the big shows high, the space behind them is empty. A quick pass to the slipping screener beats the late rotation."},
        {"question": "What is a slip screen?", "options": ["The screener leaves before making contact and cuts toward the basket", "A screen set on a defender''s back", "An illegal moving screen", "A screen set for the shooter in the corner"], "correct_index": 0, "explanation": "The slip punishes defenses that switch early or jump out high, because the screener dives while the defenders are focused on the ball."},
        {"question": "Decision point: After a switch, a small guard is now defending your center near the paint. What is usually the best way to use this?", "options": ["Have the center dribble at the top of the key", "Ignore it, it does not matter", "Have the center seal deep in the post and feed them quickly from a good angle", "Have the center set another screen"], "correct_index": 2, "explanation": "A big sealing a small defender near the rim is a high-percentage look, as long as the entry pass comes quickly."},
        {"question": "A center has switched onto your quick guard. What is usually the best approach?", "options": ["Isolate in space and attack with change of pace and direction", "Post up the center on the block", "Pass to your own center at the three-point line", "Shoot over the center from half court"], "correct_index": 0, "explanation": "Most bigs are less comfortable defending quick guards in open space, so clear room and attack their feet."},
        {"question": "Decision point: The defense switches, and as your center starts to post the smaller defender, a second defender leaves the weak side to front and help. What is the best response?", "options": ["Force the ball into the post anyway", "Call a timeout", "Let the shot clock run down", "Swing the ball to the weak side, because the helper left someone open"], "correct_index": 3, "explanation": "When the defense brings help to cover a mismatch, the ball should go to the player that helper left."},
        {"question": "What is a ghost (or fake) screen?", "options": ["A screen where both players leave the floor", "The screener approaches as if to screen, then pops or slips away without setting it", "A screen set under the basket", "A screen set by two players at once"], "correct_index": 1, "explanation": "Ghosting the screen confuses switching defenses, because they start to switch or show before any screen actually happens."}
      ]'::jsonb, 3);
  END IF;

