  UPDATE public.study_items SET quiz_questions = '[
    {"question": "What is the main goal of chopping your feet at the end of a closeout?", "options": ["To draw a charge", "To stay balanced so the shooter cannot drive straight past you", "To block every shot", "To get back on offense faster"], "correct_index": 1, "explanation": "Short, choppy steps keep you balanced, so you can contest the shot and still slide if the shooter drives."},
    {"question": "Where should a weak-side defender be when the ball is on the opposite wing?", "options": ["Face-guarding their player at the three-point line", "In the gap near the paint, seeing both their player and the ball", "At half court", "Behind the backboard"], "correct_index": 1, "explanation": "Sitting in the gap lets you stop penetration early and still recover to your player on a kick-out."},
    {"question": "What should your hands be doing as you finish a closeout?", "options": ["One hand high to contest the shot, with your body ready to slide if they drive", "Both hands behind your back", "Both hands down at your knees", "Reaching for the ball every time"], "correct_index": 0, "explanation": "A high hand bothers the shot, while staying balanced lets you react to the drive without fouling."},
    {"question": "Decision point: Your player is a strong driver but a poor shooter. The ball is swung to them. How should you close out?", "options": ["Fly at them with both hands high to block the shot", "Stay in the paint and do not close out at all", "Turn to face the ball and ignore your player", "Close out shorter and under control, giving a little space to take away the drive"], "correct_index": 3, "explanation": "Closeouts should match the player. Against a driver, a short, controlled closeout protects against the drive and still discourages the shot."},
    {"question": "What is a stunt (show and recover)?", "options": ["A full double team", "Switching onto the driver", "A quick fake step toward the ball handler to slow them, then recovering to your own player", "Leaving your player to guard the rim for the rest of the possession"], "correct_index": 2, "explanation": "A stunt makes the ball handler hesitate without fully leaving your player, buying time for the on-ball defender to recover."},
    {"question": "Decision point: You are the weak-side defender nearest the rim. The ball handler beats their defender and drives baseline. What is your job?", "options": ["Stay attached to your shooter no matter what", "Run toward half court", "Wait until the driver has already shot", "Rotate early to meet the driver before the rim and contest vertically"], "correct_index": 3, "explanation": "Help must arrive early. Meeting the driver before the rim, with a vertical contest, stops the layup without a foul."},
    {"question": "What does ball-you-player mean in help defense?", "options": ["Position yourself between the ball and your player so you can see both", "Always face your own player", "Always guard the ball", "Stand right next to your player at all times"], "correct_index": 0, "explanation": "Staying in the triangle between the ball and your player lets you help on drives and still recover to your player."}
  ]'::jsonb
  WHERE title = 'Closeouts and Help-Side Positioning' AND jsonb_array_length(quiz_questions) < 7;

  IF v_defense IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_defense AND title = 'On-Ball Defense: Stance, Slides & Keeping the Ball in Front') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_defense, 'On-Ball Defense: Stance, Slides & Keeping the Ball in Front',
      'Build a low, balanced stance, move your feet instead of reaching, and guide the ball handler where your team wants them to go.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Stay low with feet wider than your shoulders and weight on the balls of your feet', 'Slide or run to beat the ball to a spot; do not reach or cross your feet early', 'Know your team rule: push the ball toward the sideline, baseline, or help'],
      'Think about your last game. When a player beat you off the dribble, what happened first: did you reach, stand up tall, or lose your angle? Pick one habit to fix in your next session.',
      '[
        {"question": "Where should your weight be in a good defensive stance?", "options": ["On your heels, so you can drop back", "Spread evenly while standing up tall", "On the balls of your feet with knees bent and back fairly straight", "Only on your front foot"], "correct_index": 2, "explanation": "Weight on the balls of your feet with bent knees lets you push off quickly in any direction."},
        {"question": "Decision point: A quick ball handler gets a step on you going toward the sideline. What should you usually do?", "options": ["Turn and run to beat them to a spot, then get back in front", "Reach for the ball from behind", "Keep sliding slowly even though you are beaten", "Give up on the play"], "correct_index": 0, "explanation": "Once beaten, sliding is too slow. Open your hips, sprint to cut off their path, then return to your stance."},
        {"question": "Decision point: Your team rule is to keep the ball out of the middle. The ball handler is on the right wing. How should you position yourself?", "options": ["Straight up in front of them", "Behind them", "Ten feet off them", "Shaded slightly to the middle side, so the drive goes toward the sideline and baseline where help waits"], "correct_index": 3, "explanation": "Shading to the middle takes away the middle drive and pushes the ball toward areas where your teammates are ready to help."},
        {"question": "Why is reaching for the ball usually a bad habit?", "options": ["It is always a foul", "It pulls you off balance and out of position, making it easy to drive past you or foul", "The ball is too slippery", "It helps the offense see the rim"], "correct_index": 1, "explanation": "Reaching shifts your weight forward and opens your stance, which is exactly what a good driver wants."},
        {"question": "How much space should you give a ball handler?", "options": ["As close as possible every time", "About an arm''s length, adjusting for how dangerous they are as a shooter or driver", "As far as possible every time", "Stand under the basket"], "correct_index": 1, "explanation": "Arm''s length is a starting point. Tighten up on shooters and give a bit more room to quick drivers."},
        {"question": "Decision point: The ball handler picks up their dribble near the sideline. What is the best defensive move?", "options": ["Back off and let them pass", "Turn to look at the bench", "Reach in and grab the ball", "Close the space, mirror the ball with active hands, and make passing difficult"], "correct_index": 3, "explanation": "A dead ball near the sideline is an opportunity. Crowd them and mirror the ball to force a bad pass or a held ball."},
        {"question": "What is the purpose of active hands on defense?", "options": ["To take away passing lanes and bother the ball without reaching and fouling", "To wave at the referees", "To hold the offensive player", "Only to keep your balance"], "correct_index": 0, "explanation": "Active hands disrupt passes and dribbles while your feet do the real work of staying in front."}
      ]'::jsonb, 2);
  END IF;

  IF v_defense IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_defense AND title = 'Defending the Pick & Roll: Communication & Coverages') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_defense, 'Defending the Pick & Roll: Communication & Coverages',
      'Learn how defenders talk through ball screens, what drop, hedge, and switch coverages ask of each player, and how the low man protects the rim.',
      'placeholder', 'HoopIQ', 8,
      ARRAY['Call the screen early and loudly: which side and which coverage', 'Every coverage gives something up; know what your team is willing to allow', 'The weak-side low man must tag the roller so the rim is protected'],
      'In your last game or practice, did you hear screens being called before they arrived? Think of one ball screen your team got beat on. Who was supposed to talk, and what was the coverage?',
      '[
        {"question": "What should the screener''s defender call as a screen is coming?", "options": ["Nothing, because talking gives away the coverage", "The score", "The ball handler''s name", "The screen and which side it is on (for example: Screen left!) plus the coverage"], "correct_index": 3, "explanation": "An early, loud call lets the on-ball defender prepare and tells everyone which coverage is coming."},
        {"question": "In drop coverage, what is the on-ball defender''s main job?", "options": ["Switch onto the big", "Fight over the screen and chase the ball handler from behind so the big can stay back", "Go under the screen every time", "Trap the ball handler"], "correct_index": 1, "explanation": "The guard gets over the screen and pressures from behind, while the big contains in front and protects the rim."},
        {"question": "Decision point: Your team is in drop coverage. The ball handler gets downhill and the roller dives. You are the weak-side defender closest to the paint (the low man). What is your job?", "options": ["Step in and tag the roller so they cannot catch an easy layup, then recover", "Stay glued to your shooter in the corner no matter what", "Run to trap the ball handler", "Leave the paint to guard the top of the key"], "correct_index": 0, "explanation": "The low man bumps the roller to protect the rim until the big recovers, then gets back out to their own player."},
        {"question": "What is the main risk of switching every ball screen?", "options": ["There is no risk", "Switching is illegal", "It can create size mismatches that the offense will attack", "It makes the screen easier to set"], "correct_index": 2, "explanation": "Switching keeps a body in front of the ball, but can leave a small defender on a big or a big on a quick guard."},
        {"question": "What does going under a ball screen usually give up?", "options": ["Space for the ball handler to shoot a jumper", "Easy layups for the screener", "Automatic free throws", "Nothing"], "correct_index": 0, "explanation": "Going under keeps you between the ball and the rim but gives the ball handler room to pull up."},
        {"question": "Decision point: The opposing ball handler is an excellent three-point shooter coming off a high ball screen. Which choice is usually worst?", "options": ["Hedging or showing high", "Going under the screen and giving them an open pull-up three", "Trapping", "Switching"], "correct_index": 1, "explanation": "Going under concedes exactly what a great shooter wants. Against shooters, defenders fight over or bring the big up."},
        {"question": "After a hedge, what must the big defender do?", "options": ["Stay on the ball handler for the rest of the possession", "Stand at the free-throw line", "Recover quickly to the screener once the on-ball defender is back in front", "Foul the screener"], "correct_index": 2, "explanation": "The hedge is temporary. The big must sprint back to the screener before they can catch on the roll."}
      ]'::jsonb, 3);
  END IF;

