  IF v_ball IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_ball AND title = 'Protecting the Ball: Dribble Height, Off Arm & Eyes Up') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_ball, 'Protecting the Ball: Dribble Height, Off Arm & Eyes Up',
      'Learn the fundamentals of secure dribbling under pressure: dribble height, using your body and off arm as a shield, and keeping your eyes on the defense.',
      'placeholder', 'HoopIQ', 6,
      ARRAY['Dribble lower and away from the defender under pressure; higher and pushed out in front in open space', 'Keep your body between the defender and the ball, with a legal off-arm bar for protection', 'Eyes up: see the floor and the defense, not the ball'],
      'Think about any turnover you had while dribbling in your last game or session. Were you looking down, dribbling too high, or dribbling into traffic? What will you drill this week?',
      '[
        {"question": "When a defender is pressuring you closely, how should you dribble?", "options": ["High and in front of your body", "Low and on the side away from the defender, using your body as a shield", "With two hands", "As hard as possible straight down in front of you"], "correct_index": 1, "explanation": "A low dribble on your far side gives the defender less time and less ball to reach for."},
        {"question": "Why do coaches stress keeping your eyes up while dribbling?", "options": ["It looks better", "It makes the dribble faster", "It stops defenders from reaching", "You can see open teammates, help defenders, and traps before they arrive"], "correct_index": 3, "explanation": "Your eyes are your decision-making tool. Watching the ball means you see the trap only when it is too late."},
        {"question": "What is the role of the off arm (non-dribbling arm) when protecting the ball?", "options": ["To create a legal barrier and feel the defender, without pushing off", "To push the defender away", "To hold the defender''s jersey", "To hang loosely behind your back"], "correct_index": 0, "explanation": "A bent off arm creates space and tells you where the defender is. Extending it to push off is a foul."},
        {"question": "Decision point: You are bringing the ball up and a second defender comes running at you from the side to trap. What is the best first move?", "options": ["Pick up the dribble and hold the ball", "Turn your back and keep dribbling in place", "Keep your eyes up and get the ball away from the trap quickly, with a pass or a retreat dribble", "Try to dribble between both defenders every time"], "correct_index": 2, "explanation": "The best way to beat a trap is before it closes. Seeing it early lets you pass or retreat to a better angle."},
        {"question": "In open space with no defender nearby, which dribble is best for speed?", "options": ["A very low, quick dribble", "A crossover on every step", "A behind-the-back dribble", "A higher dribble pushed out in front, covering more ground with each bounce"], "correct_index": 3, "explanation": "Pushing the ball out in front lets you run at full speed and cover ground with fewer dribbles."},
        {"question": "Decision point: You catch at the top and your defender is playing you tight while your team sets up a play on the other side. What is the smartest choice?", "options": ["Dribble between your legs in place to show your skills", "Use a protective dribble with your body between the defender and the ball, eyes on the play", "Throw a quick lob across the court", "Hold the ball above your head"], "correct_index": 1, "explanation": "When you are not attacking, your job is to keep the ball safe and see the floor until the play develops."},
        {"question": "Decision point: You are dribbling up the court in transition with a defender chasing from behind on your right side. Which habit is most likely to get you stripped?", "options": ["Using your off arm to protect the ball", "Dribbling with your eyes up", "Dribbling out in front with your right hand, on the side closest to the chasing defender", "Switching hands to keep the ball away from them"], "correct_index": 2, "explanation": "Chasing defenders poke at the ball on their side. Keep it on the hand away from them and protected by your body."}
      ]'::jsonb, 1);
  END IF;

  IF v_ball IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_ball AND title = 'Change of Pace & Direction: Beating Your Defender') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_ball, 'Change of Pace & Direction: Beating Your Defender',
      'Speed alone is not enough. Learn how hesitation, change of pace, and well-timed crossovers make defenders commit and open driving lanes.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Slow to fast beats fast to fast: changing speed freezes the defender', 'Attack the defender''s front foot and cross back when they overcommit', 'Every move should create an advantage: a lane, a shot, or a pass, not just a highlight'],
      'In your last game, how many times did you beat your defender off the dribble? Did you use a change of pace, or did you just try to be faster? Which move led to a good shot for you or a teammate?',
      '[
        {"question": "Why is a hesitation dribble effective?", "options": ["It makes the defender stand up or relax, and then you explode past them", "It slows the game down for the rest of the possession", "It forces the defender into a violation", "It is always a foul on the defense"], "correct_index": 0, "explanation": "Defenders react to your speed. When you slow down, they relax for a moment, and that moment is when you go."},
        {"question": "What does attacking the defender''s front (lead) foot mean?", "options": ["Stepping on their toes", "Bouncing the ball off their foot", "Driving past the side where their foot is forward, because they must turn their hips to recover", "Driving straight at their chest"], "correct_index": 2, "explanation": "A defender with one foot forward has to open their hips to slide that way, which is slower than a simple slide."},
        {"question": "Decision point: You attack right, and your defender slides hard to cut you off, overplaying your right hand. What is the best counter?", "options": ["Keep driving right into their chest", "Stop and pass back every time", "Pick up the ball and look around", "Cross over or spin back to your left, attacking the space they just left"], "correct_index": 3, "explanation": "When a defender overcommits, the space they came from is open. Change direction to attack it."},
        {"question": "What is a common mistake when using dribble moves?", "options": ["Using a move to create a real advantage", "Making the move too far from the defender, so they do not have to react", "Changing speed", "Keeping the ball protected"], "correct_index": 1, "explanation": "A move only works when the defender is close enough to react to it. Moves made from far away just waste time."},
        {"question": "When is a crossover most likely to be stolen?", "options": ["When it is low and quick", "When it is wide and high in front of a defender who is close", "When the defender is far away", "When you do it with your eyes up"], "correct_index": 1, "explanation": "A wide, high crossover spends a long time in front of the defender''s hands. Keep it low, quick, and tight."},
        {"question": "Decision point: After a switch, a bigger, slower defender is guarding you and sitting back, giving you space. What is the best approach?", "options": ["Shoot a deep contested shot right away", "Post up the bigger defender", "Pass to the corner without looking", "Use change of pace to get them moving and attack their feet, or take the open jumper if they sit too far back"], "correct_index": 3, "explanation": "Make the bigger defender move laterally, where they are weakest, and punish them if they give too much space."},
        {"question": "What should come right after you beat your defender off the dribble?", "options": ["Celebrate the move", "Slow down and wait", "Read the help defense: finish, pull up, or pass to the player whose defender helped", "Dribble back out and try the move again"], "correct_index": 2, "explanation": "Beating your defender is only step one. The help defender now decides whether you score or a teammate does."}
      ]'::jsonb, 2);
  END IF;

  IF v_ball IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_ball AND title = 'Handling Pressure & Traps') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_ball, 'Handling Pressure & Traps',
      'Stay calm against full-court pressure and traps: use angles, pass early, and know where your outlets are.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Beat the trap before it forms: see it coming and pass early', 'If you are trapped, stay low, pivot, and look over the top or to the middle outlet', 'Pressure creates advantages: once you break it, attack before the defense recovers'],
      'Did your team face pressure or a trap recently? Think about one possession: did you panic, or did you find the outlet? Where on the floor did you get trapped, and why?',
      '[
        {"question": "Where are the most common trapping spots on the court?", "options": ["The middle of the court", "Under your own basket", "The free-throw line", "The corners and sidelines, especially near half court, where the lines act like extra defenders"], "correct_index": 3, "explanation": "Sidelines, corners, and the half-court line limit where you can go, so defenses love to trap there."},
        {"question": "Decision point: You got caught in a trap and have already picked up your dribble. What is the best technique?", "options": ["Hold the ball high above your head and turn away", "Jump in the air and then look for a pass", "Stay low, pivot to protect the ball, and use ball fakes to open a passing lane", "Throw the ball off a defender''s leg"], "correct_index": 2, "explanation": "Staying low and pivoting keeps the ball away from reaching hands, and fakes move the defenders to open passing lanes."},
        {"question": "Decision point: The other team is pressing full court. You catch the inbound pass and see a second defender running at you. Your teammate in the middle of the floor is open. What is the best play?", "options": ["Pass to the middle before the trap closes", "Dribble toward the sideline to escape", "Pick up the ball and wait", "Throw a long pass to the far basket over everyone"], "correct_index": 0, "explanation": "The middle of the floor is the key to breaking pressure. Getting the ball there before the trap arrives puts the defense behind the play."},
        {"question": "Decision point: You break the press and your team now has a 3-on-2 in the frontcourt. What should you do?", "options": ["Pull the ball back out and set up the offense", "Hold the ball and run clock", "Attack right away, because pressure often leaves the rim exposed", "Pass back to the inbounder"], "correct_index": 2, "explanation": "Pressing teams take risks. When you beat the pressure, punish it by attacking the numbers advantage."},
        {"question": "Why is a lob pass over a trap risky?", "options": ["It is illegal", "It hangs in the air long enough for defenders to recover and intercept", "It moves too fast to catch", "Lobs are always caught"], "correct_index": 1, "explanation": "Slow, floating passes give defenders time to read and jump the lane. Crisp passes are safer."},
        {"question": "What should teammates do when the ball handler gets trapped?", "options": ["Stand still and watch", "Move into open passing lanes, especially a middle outlet and a safety behind the ball", "Run to the other end of the court", "Come and stand right next to the trap"], "correct_index": 1, "explanation": "A trapped player needs targets. Teammates must move to open, reachable spots, not stand still or crowd the ball."},
        {"question": "What is the best long-term way to handle pressure?", "options": ["Stay calm, see it early, and move the ball with the pass before the defense can set the trap", "Dribble faster in every situation", "Always call a timeout", "Throw the ball away and reset"], "correct_index": 0, "explanation": "The pass is faster than any dribbler. Composure and early passes break pressure more reliably than dribbling through it."}
      ]'::jsonb, 3);
  END IF;

  -- ---------------------------------------------------------------------------
  -- Spacing & Off-Ball Movement
  -- ---------------------------------------------------------------------------
  IF v_spacing IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_spacing AND title = 'Floor Spacing Fundamentals: The Spots & Staying Spaced') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_spacing, 'Floor Spacing Fundamentals: The Spots & Staying Spaced',
      'Understand why good spacing makes every drive and pass easier, where the key spots are, and how far apart teammates should be.',
      'placeholder', 'HoopIQ', 6,
      ARRAY['Keep roughly 12 to 15 feet between teammates so one defender cannot guard two players', 'Fill the corners and wings; spacers must be threats, not spectators', 'When the ball moves, the spacing adjusts: drift, lift, or fill behind the drive'],
      'Think back to your last game. Were there moments when two teammates stood close together, or when you drifted into the same area as the ball? How did that affect the drive or pass?',
      '[
        {"question": "Why does good spacing help the offense?", "options": ["It makes the court physically bigger", "It lets players rest", "It forces each defender to cover more ground, opening driving lanes and passing windows", "It slows the pace down"], "correct_index": 2, "explanation": "Spread-out offensive players stretch the defense, so help has farther to travel and gaps appear."},
        {"question": "About how far apart should offensive teammates usually be?", "options": ["Roughly 12 to 15 feet, so one defender cannot guard two players", "About 3 feet", "At least half the court", "Distance does not matter"], "correct_index": 0, "explanation": "At that distance, a defender who helps on one player leaves the other open."},
        {"question": "Decision point: Your teammate drives baseline from the wing. You are in the corner on that same side. What should you do?", "options": ["Stay in the corner and watch", "Run toward the ball to help", "Cut to the free-throw line and stand still", "Lift up toward the wing or slide behind the play to create a passing angle and keep spacing"], "correct_index": 3, "explanation": "A baseline drive heads right into your corner. Moving out of the way and into a new passing angle gives the driver a kick-out option."},
        {"question": "Why are the corners especially valuable spots?", "options": ["They are closest to the bench", "The corner three is often a shorter three, and corner spacing pulls help defenders away from the paint", "Defenders are not allowed to guard the corner", "Corner shots are worth extra points"], "correct_index": 1, "explanation": "A shooter in the corner forces the defense to choose between helping in the paint and staying home."},
        {"question": "What does it mean to be a spacer who is a threat?", "options": ["Standing still in the corner", "Hiding from the ball", "Waving your arms", "Being ready to shoot, drive, or cut when the ball comes, so your defender cannot leave to help"], "correct_index": 3, "explanation": "If your defender does not respect you, they help on the ball. Being ready to act keeps them attached to you."},
        {"question": "Decision point: A teammate drives middle from the top, and your defender on the wing steps in to help. What should you do?", "options": ["Stay spaced, show your hands, and be ready for the kick-out", "Run into the paint beside the driver", "Call for a screen", "Walk toward half court"], "correct_index": 0, "explanation": "Your defender helping is your cue. Stay in the driver''s vision, ready to catch and shoot or attack the closeout."},
        {"question": "What happens when two offensive players stand too close together?", "options": ["Nothing changes", "One defender can guard both, and help defense becomes easy", "The offense scores more", "The referee calls a violation"], "correct_index": 1, "explanation": "Crowding lets one defender cover two players, which frees another defender to help."}
      ]'::jsonb, 1);
  END IF;

  IF v_spacing IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_spacing AND title = 'Cutting: Backdoors, Basket Cuts & Reading Your Defender') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_spacing, 'Cutting: Backdoors, Basket Cuts & Reading Your Defender',
      'Great off-ball players read their defender and cut at the right moment. Learn backdoor, basket, flash, and V-cuts and the cues that trigger each.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Read your defender: if they deny, go backdoor; if they turn their head, cut behind them', 'Cut with purpose and at full speed, then fill an open spot if you do not get the ball', 'Timing matters: cut when the passer can see you and deliver the ball'],
      'Think about your last game. How many times did you cut hard to the basket? Was there a moment when your defender turned their head or overplayed you and you missed the chance to cut?',
      '[
        {"question": "Decision point: You are on the wing and your defender is overplaying you hard, with a hand in the passing lane. What is the best cut?", "options": ["Keep fighting to get open on the wing", "Stand still and wait", "Run to the corner", "Plant your outside foot and cut backdoor to the basket"], "correct_index": 3, "explanation": "An overplaying defender has given up the space behind them. The backdoor cut takes it."},
        {"question": "What is a good cue to cut when your defender is in help position?", "options": ["They move closer to you", "They are facing you", "They turn their head to watch the ball", "They call a switch"], "correct_index": 2, "explanation": "When a defender loses sight of you, a quick cut behind them is hard to recover from."},
        {"question": "What should you do if you cut and do not receive the ball?", "options": ["Keep going and fill an open spot to keep the floor spaced", "Stand under the basket", "Ask for the ball again right away", "Stop in the lane and wait"], "correct_index": 0, "explanation": "A cut that ends in the lane clogs the floor. Clear out and refill a spot so the next action has space."},
        {"question": "What is a flash cut?", "options": ["A backdoor cut", "A cut to the corner", "A quick cut into an open space in the middle of the floor, often to the high post or elbow, to give the ball handler an outlet", "A cut after a made free throw"], "correct_index": 2, "explanation": "Flash cuts fill open space in the middle of the defense and are great outlets against pressure and zones."},
        {"question": "Decision point: Your teammate is driving, and your defender on the weak-side wing sags into the lane to help. What is a strong move?", "options": ["Stand behind the three-point line with your hands down", "Cut behind the helping defender to the rim, or drift to an open spot in the driver''s line of sight", "Call for a timeout", "Run toward the ball handler for a handoff"], "correct_index": 1, "explanation": "A helping defender cannot watch you and the ball at the same time. Cut behind them or move into an open passing window."},
        {"question": "Why should cuts be made at full speed?", "options": ["Slow cuts are easier to defend and throw off the passer''s timing", "Referees prefer it", "It makes you tired", "Only fast cuts are allowed"], "correct_index": 0, "explanation": "A hard cut forces the defense to react and tells the passer you are serious about getting open."},
        {"question": "Decision point: Your defender is denying you on the wing and you want to catch at the three-point line instead of going backdoor. Which cut helps?", "options": ["Set a screen for a teammate", "A V-cut: walk your defender toward the lane, then explode back out to the wing to catch", "Stand still and call for the ball", "Run to the opposite corner"], "correct_index": 1, "explanation": "The V-cut uses a change of direction and speed to create separation for a catch on the perimeter."}
      ]'::jsonb, 2);
  END IF;

  IF v_spacing IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_spacing AND title = 'Off-Ball Screens: Setting & Using Screens Away') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_spacing, 'Off-Ball Screens: Setting & Using Screens Away',
      'Learn to set legal, effective off-ball screens and read how your defender plays them: curl, pop, flare, or backdoor.',
      'placeholder', 'HoopIQ', 8,
      ARRAY['Wait for the screen: set your defender up, then come off shoulder to shoulder with the screener', 'Read the defender: trailing means curl, going under means pop or flare, cheating over means backdoor', 'The screener is often open too: slip, seal, or pop after the screen'],
      'In your last practice or game, did you set or use an off-ball screen? Did you read your defender or run the same cut every time? Describe what the defender did and what the best read would have been.',
      '[
        {"question": "What should you do before using an off-ball screen?", "options": ["Walk your defender into the screen with a set-up step, then come off shoulder to shoulder", "Run past the screen before it is set", "Stand next to the screener and wait", "Point at the screener and call their name"], "correct_index": 0, "explanation": "Setting your defender up and waiting for the screen makes sure the screener actually gets a piece of your defender."},
        {"question": "Decision point: You come off a down screen and your defender is trailing right behind you, chasing. What is the best cut?", "options": ["Pop out to the three-point line", "Stop behind the screen", "Fade to the corner", "Curl tightly around the screen toward the basket"], "correct_index": 3, "explanation": "A trailing defender is behind you, so curling toward the rim keeps them stuck behind the screen."},
        {"question": "Decision point: Your defender goes under the screen to beat you to your spot. What is the best read?", "options": ["Curl to the basket", "Stand still", "Pop out or flare away for an open jumper, since they went under", "Run back to where you started"], "correct_index": 2, "explanation": "Going under leaves space on the perimeter. Popping out gives you an open catch-and-shoot look."},
        {"question": "Which describes a legal screen?", "options": ["Moving into the defender at the last moment", "Being stationary, upright, with arms kept in to your body", "Holding the defender''s arm", "Sticking out a leg or hip as the defender passes"], "correct_index": 1, "explanation": "A legal screen is set and still, with arms in. Moving or reaching turns a great screen into a turnover."},
        {"question": "Why is the screener often open after the screen?", "options": ["The screener is always the best shooter", "The screener gets free throws", "Screeners are not allowed to be guarded", "Their defender often helps on the cutter, leaving the screener free to slip, seal, or pop"], "correct_index": 3, "explanation": "Two defenders focus on one cutter, which leaves the screener with space if they move right after screening."},
        {"question": "Decision point: As you approach the screen, you see your defender cheating over the top early to beat you. What is the best read?", "options": ["Continue the curl right into them", "Cut backdoor behind them toward the basket", "Stop and ask for a new play", "Run to the corner"], "correct_index": 1, "explanation": "A defender who jumps the screen early has given up the space behind them, so go backdoor."},
        {"question": "What is a flare screen?", "options": ["A screen set on the ball handler", "A back screen for a lob", "A screen that lets the cutter move away from the ball toward the sideline or wing for a jumper", "A screen set under the basket"], "correct_index": 2, "explanation": "The flare screen moves a shooter away from the ball, which is hard to defend because the defender must fight through while looking away."}
      ]'::jsonb, 3);
  END IF;

  -- ---------------------------------------------------------------------------
  -- Transition
  -- ---------------------------------------------------------------------------
  IF v_transition IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_transition AND title = 'Running the Floor: Lanes, Rim Runs & Early Offense') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_transition, 'Running the Floor: Lanes, Rim Runs & Early Offense',
      'Learn how to fill lanes after a rebound or turnover, why rim runs matter, and how to create advantages before the defense gets set.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Get wide and fill the lanes: wings run wide near the sidelines while a big runs to the rim', 'Advance the ball with the pass when possible, because the ball moves faster than any dribbler', 'Attack before the defense is set, but take good shots, not rushed ones'],
      'Think about your team''s last fast break. Were the lanes filled wide, or did everyone run toward the ball? Did you sprint the floor every time, or pick your moments?',
      '[
        {"question": "Why should wings run wide on a fast break?", "options": ["To get away from the play", "To stretch the defense and create passing angles and driving lanes", "To rest", "Because the middle lane is illegal"], "correct_index": 1, "explanation": "Wide lanes spread the retreating defenders so the ball handler has space and options."},
        {"question": "What is a rim run?", "options": ["Running along the three-point line", "Running to the corner", "A defensive sprint back", "A big or forward sprinting straight down the middle to the rim, forcing the defense to protect the basket"], "correct_index": 3, "explanation": "A rim runner pulls defenders toward the basket, which opens the wings and trailers."},
        {"question": "Decision point: You grab a defensive rebound and see a teammate already sprinting ahead of everyone. What is the best play?", "options": ["Make an accurate outlet or ahead pass to that teammate early", "Dribble the whole way yourself", "Hold the ball and wait for everyone to set up", "Pass to the nearest teammate standing still"], "correct_index": 0, "explanation": "An early, on-target ahead pass turns a sprint into an easy basket before the defense recovers."},
        {"question": "What is the main advantage of early offense?", "options": ["It takes more time off the clock", "It avoids shooting", "It lets you attack before the defense is organized, matched up, and ready to help", "It is easier on your legs"], "correct_index": 2, "explanation": "Defenses are weakest when they are still running back and finding their players."},
        {"question": "Decision point: You are leading a 2-on-1. The lone defender stays in the middle between you and your teammate. What should you do?", "options": ["Pass immediately from half court", "Stop and set up the offense", "Attack to make the defender commit, then pass or finish based on what they do", "Shoot a long three"], "correct_index": 2, "explanation": "The defender cannot guard both of you. Attack to force a decision, then take what they give you."},
        {"question": "What is a trailer in transition?", "options": ["The last defender back", "A player who never runs", "The referee", "A player, often a big, who arrives behind the first wave and is ready for a pass, shot, or quick action"], "correct_index": 3, "explanation": "Trailers catch the defense focused on the first wave, often creating open shots or quick screens."},
        {"question": "Decision point: You push the ball up the floor, but all five defenders are back and matched up. What is the smartest choice?", "options": ["Force a contested layup", "Pull it out and flow into your half-court offense", "Shoot a quick deep three", "Throw a lob to a covered teammate"], "correct_index": 1, "explanation": "Early offense is about taking advantages. If there is no advantage, get into your offense without wasting the possession."}
      ]'::jsonb, 1);
  END IF;

  IF v_transition IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_transition AND title = 'Transition Defense: Getting Back & Stopping the Ball') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_transition, 'Transition Defense: Getting Back & Stopping the Ball',
      'The first few seconds after a missed shot or turnover decide many possessions. Learn sprint-back habits, stopping the ball, protecting the rim, and matching up.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Sprint back first, find the ball, then find a player', 'Stop the ball and protect the rim before anything else', 'Talk constantly: call ball, call matchups, and point to open players'],
      'Think about the last easy basket your team gave up in transition. Was it a turnover, a long rebound, or players not sprinting back? What was your role in it?',
      '[
        {"question": "What is the first priority in transition defense?", "options": ["Finding your own player", "Arguing the call", "Sprinting back to protect the basket and stopping the ball", "Crashing the offensive glass every time"], "correct_index": 2, "explanation": "Layups are the most valuable shots. Protect the rim and slow the ball first, then sort out matchups."},
        {"question": "Decision point: After a turnover, the other team has a 2-on-1 against you. What should you do?", "options": ["Stay between them near the paint, fake at the ball handler, and try to make them pass while your teammates recover", "Run straight at the ball handler at half court", "Guard only the player without the ball", "Give up the layup and wait for teammates"], "correct_index": 0, "explanation": "Buying time is the goal. Protect the rim, show at the ball, and force extra passes until help arrives."},
        {"question": "What should you do when you get back but are not near your own player?", "options": ["Run across the floor to find your original player no matter what", "Stand under the basket", "Stop running", "Match up with the nearest open threat, then communicate to switch back when it is safe"], "correct_index": 3, "explanation": "In transition, guarding the closest dangerous player beats running past open shooters to find your own."},
        {"question": "Why is communication so important in transition defense?", "options": ["Referees reward talking", "Everyone is running and cannot see the whole floor, so calling ball and matchups prevents open shots", "It slows down the offense", "It is not important"], "correct_index": 1, "explanation": "Talking fills in what teammates cannot see, so nobody is left unguarded."},
        {"question": "What does it mean to build a wall in transition defense?", "options": ["Defenders line up at half court", "Players get in front of the ball early so the ball handler has no straight line to the rim", "Defenders stand along the baseline", "Players lock arms"], "correct_index": 1, "explanation": "A wall of defenders in front of the ball forces the offense to slow down and play in the half court."},
        {"question": "Decision point: You miss a shot and the other team grabs the rebound. You are the closest player to their rebounder. What is a good play?", "options": ["Grab their jersey", "Turn and walk back", "Briefly pressure or slow the outlet pass, then sprint back", "Argue with the referee"], "correct_index": 2, "explanation": "Delaying the outlet for a second gives your teammates time to get back, as long as you then sprint back yourself."},
        {"question": "When should you point at an open player in transition?", "options": ["When you see an unguarded opponent, so a teammate can pick them up", "Never, just run", "Only after timeouts", "When you want the ball"], "correct_index": 0, "explanation": "Pointing and calling out open players helps the whole defense match up quickly."}
      ]'::jsonb, 2);
  END IF;

  IF v_transition IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_transition AND title = 'Numbers Advantages: 2-on-1, 3-on-2 & Finishing the Break') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_transition, 'Numbers Advantages: 2-on-1, 3-on-2 & Finishing the Break',
      'Convert fast-break advantages into high-quality shots by making defenders commit, keeping the floor spread, and making simple passes.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Make the defender commit before you pass', 'Keep the floor spread; do not bunch up near the ball', 'Simple passes beat flashy ones: pass early, on target, and in stride'],
      'Recall a fast break from a recent game or scrimmage where you had more players than the defense. Did your team score? If not, what went wrong: the pass, the spacing, or the decision?',
      '[
        {"question": "Decision point: You have the ball on a 3-on-2. The top defender stops you at the free-throw line and the bottom defender stays under the rim. What is the best read?", "options": ["Shoot the free-throw line jumper over the defender", "Try to dribble past both defenders", "Stop and wait for the trailers", "Pass to a wing; the bottom defender must step out, which opens the rim or the other wing"], "correct_index": 3, "explanation": "Passing to the wing forces the bottom defender to choose, and whichever player they leave becomes the open shot."},
        {"question": "In a 2-on-1, when should the ball handler pass?", "options": ["When the defender commits to stopping the ball", "As early as possible, before crossing half court", "Never, always shoot", "Only if the defender fouls"], "correct_index": 0, "explanation": "Attack until the defender commits to you. Passing too early lets one defender guard both players."},
        {"question": "What is a common mistake on the fast break?", "options": ["Keeping the lanes wide", "Passing early", "Over-dribbling and bunching up near the ball, which lets the defense catch up", "Filling the lanes"], "correct_index": 2, "explanation": "Extra dribbles and crowded spacing give recovering defenders the time and angles they need."},
        {"question": "Why are bounce passes often used on a 2-on-1 near the rim?", "options": ["They are always faster", "They are harder for a tall defender to deflect and easier for a running teammate to catch in stride", "They are worth more points", "The rules require them"], "correct_index": 1, "explanation": "Defenders reaching up have a hard time getting low to deflect a bounce pass, and it arrives at a catchable height."},
        {"question": "Decision point: You are the wing on a 3-on-2. The ball is passed to you and the bottom defender steps out to guard you. What is the best play?", "options": ["Pass right away to the teammate cutting to the rim or the opposite wing, since the rim is now open", "Pull up for a contested jumper", "Dribble back out", "Hold the ball"], "correct_index": 0, "explanation": "The bottom defender leaving the rim is the moment. A quick pass to the open teammate gets a layup or open shot."},
        {"question": "What should the player without the ball do on a 2-on-1?", "options": ["Run behind the ball handler", "Stop running", "Run close to the ball handler", "Stay wide and even with or slightly ahead of the ball, ready to catch and finish"], "correct_index": 3, "explanation": "Staying wide and ahead makes the defender cover more ground and keeps a passing lane open."},
        {"question": "What makes a trailer valuable after the first wave?", "options": ["They always shoot threes", "They arrive while defenders are focused on the first wave, creating an open shot, drive, or quick screen", "They are the best defenders", "They take the ball out of bounds"], "correct_index": 1, "explanation": "Defenses often lose track of trailers, so a well-timed trailer creates a second advantage."}
      ]'::jsonb, 3);
  END IF;

  -- ---------------------------------------------------------------------------
  -- Reading the Game & Film Study
  -- ---------------------------------------------------------------------------
  IF v_film IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_film AND title = 'How to Watch Film: Studying Yourself') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_film, 'How to Watch Film: Studying Yourself',
      'Film is only useful if you know what to look for. Learn a simple process for reviewing your own games: watch with a focus, track decisions, and turn clips into goals.',
      'placeholder', 'HoopIQ', 8,
      ARRAY['Watch with one focus at a time: decisions, defense, or effort, not everything at once', 'Judge the decision, not only the result: a good shot can miss and a bad pass can work', 'Turn what you see into one or two specific practice goals'],
      'Pick one clip from your most recent game or session. Describe what happened, whether it was a good decision, and one thing you will practise because of it.',
      '[
        {"question": "What is the best way to start reviewing your own game film?", "options": ["Only watch your made shots", "Watch with one clear focus, such as your defense or your decisions with the ball", "Watch it once at double speed", "Skip the parts where you are off the ball"], "correct_index": 1, "explanation": "A single focus keeps you from getting overwhelmed and makes it easier to spot patterns."},
        {"question": "Why should you judge the decision, not only the result?", "options": ["Results do not matter at all", "Coaches only care about effort", "It is quicker", "A good decision can end in a miss and a bad one can get lucky, and decisions are what you can repeat"], "correct_index": 3, "explanation": "Over a season, good decisions produce good results. Grading decisions helps you build habits that last."},
        {"question": "Why is it valuable to watch what you do off the ball?", "options": ["Most of the game is played without the ball, so cutting, spacing, and defensive habits show up there", "It is not valuable", "To count how many times you touched the ball", "To see the crowd"], "correct_index": 0, "explanation": "Even the busiest ball handler spends most of a game without the ball. Off-ball habits often decide possessions."},
        {"question": "Decision point: On film, you see yourself standing still on the weak side for five straight possessions. What is the best takeaway?", "options": ["Your teammates should pass more", "It does not matter, since you were not near the ball", "Set a goal to cut, relocate, or screen more when the ball is away from you", "Ask to play a different position"], "correct_index": 2, "explanation": "Standing still makes you easy to guard and lets your defender help. Film showed you a clear habit to change."},
        {"question": "What is a useful way to track your decisions on film?", "options": ["Count how many times you dribbled", "Tally good and poor reads in simple categories, like shot selection, passes, and turnovers", "Only count your points", "Guess from memory later"], "correct_index": 1, "explanation": "Simple tallies turn film into data, so you can see real trends instead of relying on how the game felt."},
        {"question": "Decision point: On film, you notice most of your turnovers happen when you drive left. What is the best plan?", "options": ["Build a focused left-hand ball-handling and finishing plan and track it over the next few games", "Never drive left again", "Ignore it, since it might be random", "Only pass from now on"], "correct_index": 0, "explanation": "Film found a weakness. A focused plan plus tracking turns it into improvement instead of avoidance."},
        {"question": "How often is it helpful to review film?", "options": ["Only at the end of the season", "Never, feel is enough", "Regularly, in short focused sessions soon after games, while you still remember what you were thinking", "Only after you play badly"], "correct_index": 2, "explanation": "Short, regular reviews build the habit and connect what you saw on film with what you felt in the moment."}
      ]'::jsonb, 1);
  END IF;

  IF v_film IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_film AND title = 'Scouting an Opponent: Tendencies & Personnel') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_film, 'Scouting an Opponent: Tendencies & Personnel',
      'Learn how to watch an opponent and find their tendencies: who shoots, who drives, which hand they prefer, and what plays they run.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Know the personnel: shooters, drivers, and non-shooters are guarded differently', 'Look for tendencies: favorite hand, favorite spot, and go-to plays after timeouts', 'Turn scouting into short, simple rules the team can remember during the game'],
      'Think about the last team you played. Could you name their best shooter and their best driver before the game? What is one tendency you noticed during the game that you could have used earlier?',
      '[
        {"question": "What is personnel scouting?", "options": ["Counting how many players are on the roster", "Learning the names of the coaches", "Knowing each opponent''s strengths and weaknesses, like who shoots well, who drives, and which hand they prefer", "Checking their uniform colors"], "correct_index": 2, "explanation": "Personnel scouting tells you how to guard each player, not just what plays the team runs."},
        {"question": "Decision point: The scouting report says your matchup is a great driver but rarely shoots threes. How should you guard them?", "options": ["Give a little extra space to protect against the drive, and contest shots under control", "Press up tight and try to steal every dribble", "Leave them to double team someone else every time", "Guard them exactly like a great shooter"], "correct_index": 0, "explanation": "Give non-shooters a little space and take away what they do best: getting to the rim."},
        {"question": "Decision point: The scouting report says your matchup goes right almost every time. How should you use this?", "options": ["Ignore it", "Guard them the same as anyone else", "Stand far back", "Shade slightly to their right to push them toward their weaker left hand"], "correct_index": 3, "explanation": "Shading toward their strong hand makes them use their weaker side, where they are less comfortable."},
        {"question": "What is a good way to share scouting information with teammates?", "options": ["A long list of every detail", "Short, simple rules that are easy to remember in the game, like: Number 5, force left", "Tell them after the game", "Keep it to yourself"], "correct_index": 1, "explanation": "In the middle of a game, players remember short rules, not long reports."},
        {"question": "Decision point: In the first quarter you notice the opponent runs the same play after every timeout: a back screen for a lob. What is the smartest move?", "options": ["Wait until halftime to mention it", "Ignore it, as they might change", "Tell your teammates and coach so the team can call it out and defend the screen early", "Leave your own player to guard the rim every possession"], "correct_index": 2, "explanation": "In-game scouting is just as valuable as pre-game scouting, but only if you share it quickly."},
        {"question": "What is a tendency?", "options": ["A rule of the game", "A random event", "A type of foul", "Something a player or team does often in a certain situation, like always driving right from the left wing"], "correct_index": 3, "explanation": "Tendencies are habits. Knowing them lets you predict and take away what an opponent wants to do."},
        {"question": "Why is scouting useful even at youth and high school levels?", "options": ["It lets you skip practice", "It helps you prepare and react faster because you know what to expect", "It guarantees a win", "It is only useful for professionals"], "correct_index": 1, "explanation": "Knowing what is coming lets you make decisions earlier, which is a big edge at any level."}
      ]'::jsonb, 2);
  END IF;

  IF v_film IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_film AND title = 'Reading the Defense in Real Time') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_film, 'Reading the Defense in Real Time',
      'Recognize defensive schemes and positioning during live play: man or zone, where help is coming from, and how to spot the open player before it happens.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Scan before you catch: know where the help is before the ball arrives', 'Identify the defense early: man, zone, switching, or trapping', 'Find the helper: when a defender helps, the player they left is often open'],
      'In your last game, did you look at the defense before you caught the ball? Think of one possession where you caught it and then saw something too late. What would a pre-catch scan have shown you?',
      '[
        {"question": "What does scanning before the catch mean?", "options": ["Looking at the defense and your teammates before the ball arrives, so you already know your next move", "Looking at the scoreboard", "Watching only the ball", "Checking your shoes"], "correct_index": 0, "explanation": "Players who scan early decide faster, because they already have the picture when the ball arrives."},
        {"question": "How can you tell the other team is playing zone rather than man-to-man?", "options": ["The defenders talk", "The defense wears different colors", "The defense stays near half court", "When players cut through, defenders stay in their areas instead of following them"], "correct_index": 3, "explanation": "Send a cutter through. If nobody follows them, the defense is guarding areas, not players."},
        {"question": "Decision point: You drive middle and see the weak-side corner defender step into the paint to help. Where is the open pass most likely to be?", "options": ["The top of the key", "Back to the inbounder", "The weak-side corner, where the helper came from", "The strong-side wing, where nobody moved"], "correct_index": 2, "explanation": "The helper left their player. That player, usually in the corner, is the most likely open shot."},
        {"question": "Decision point: The defense is in a zone. Where should your team try to get the ball?", "options": ["Directly under the basket, standing still", "Into the gaps between defenders and the high post in the middle of the zone", "Only to the corners every time", "Back to half court"], "correct_index": 1, "explanation": "Zones struggle when the ball gets into gaps and the middle, because two defenders have to decide who guards it."},
        {"question": "Decision point: Before you catch on the wing, you notice your defender is playing far off you and help is packed in the paint. What should you be ready to do?", "options": ["Drive into the crowded paint right away", "Pass back without looking", "Hold the ball", "Shoot the open catch-and-shoot jumper if you are a capable shooter"], "correct_index": 3, "explanation": "The defense is daring you to shoot and taking away the paint. If it is your shot, take it."},
        {"question": "What is the low man in help defense, and why should the offense notice them?", "options": ["The referee under the basket", "The weak-side defender responsible for helping at the rim; moving them opens corner shots and lobs", "The best offensive player", "The shortest player on the floor"], "correct_index": 1, "explanation": "The low man protects the rim. When they rotate, someone on the weak side is usually left open."},
        {"question": "Why should you read the help defender instead of only your own defender when driving?", "options": ["Your own defender is not important", "The help defender cannot move", "The help defender decides whether you finish or pass, because whoever they leave is likely open", "It is a rule"], "correct_index": 2, "explanation": "Once you beat your defender, the helper''s choice creates the next advantage."}
      ]'::jsonb, 3);
  END IF;

