  IF v_rebounding IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_rebounding AND title = 'Box Out Fundamentals: Find, Hit, Get') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_rebounding, 'Box Out Fundamentals: Find, Hit, Get',
      'Rebounding is a habit. Learn to find your player on every shot, make contact first, and pursue the ball with two hands.',
      'placeholder', 'HoopIQ', 6,
      ARRAY['Find your player as the shot goes up, then make contact first', 'Stay low and wide with arms out, holding your ground', 'Pursue the ball and secure it with two hands, then chin it'],
      'Think about the last offensive rebound your team gave up. Who was your player, and did you make contact first? How many box outs did you make in your last game or practice?',
      '[
        {"question": "What does find, hit, get mean in rebounding?", "options": ["Find the ball, hit the rim, get the points", "Find the coach, hit the floor, get back", "Find the open player, hit them with a pass, get open", "Find your player, make contact to box them out, then go get the ball"], "correct_index": 3, "explanation": "The order matters: locate your player, take away their path with contact, then chase the ball."},
        {"question": "When should you make contact with the player you are boxing out?", "options": ["After the ball hits the rim", "As soon as the shot goes up, before they can get a running start", "After you catch the ball", "Never, just jump"], "correct_index": 1, "explanation": "Early contact stops the offensive player from building momentum toward the rim."},
        {"question": "What should your body position be when boxing out?", "options": ["Low and wide, with your backside into the opponent and arms out", "Upright with your arms down", "Facing the opponent", "Balanced on one leg"], "correct_index": 0, "explanation": "A low, wide base is hard to move and takes up space, keeping your opponent behind you."},
        {"question": "Decision point: A shot goes up from the wing. You are guarding a weak-side player who is already cutting toward the rim. What is the best move?", "options": ["Turn to watch the ball first", "Run toward the shooter", "Step into their path to make contact, then turn and box out", "Jump for the ball immediately"], "correct_index": 2, "explanation": "Meeting a crashing player early, before they get inside position, is the only way to keep them off the glass."},
        {"question": "Where do many missed shots from the wing or corner bounce?", "options": ["To the opposite side of the rim from where the shot was taken", "Straight back to the shooter every time", "Always to the free-throw line", "Out of bounds"], "correct_index": 0, "explanation": "Misses from the side often carry to the weak side, which is why the weak-side box out is so important."},
        {"question": "What does chinning the ball mean?", "options": ["Hitting the ball with your chin", "Securing the ball with two hands under your chin, elbows out, to protect it", "Tossing the ball up in the air", "Holding the ball below your waist"], "correct_index": 1, "explanation": "Chinning the ball keeps it high and protected from smaller players reaching in after the rebound."},
        {"question": "Decision point: You box out well, but the ball bounces long toward the free-throw line. What should you do?", "options": ["Stay in your box out and watch", "Wait for the ball to come to you", "Release and aggressively pursue the ball", "Call a timeout"], "correct_index": 2, "explanation": "The box out is not the end goal. When the ball comes off long, go get it before someone else does."}
      ]'::jsonb, 1);
  END IF;

  IF v_rebounding IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_rebounding AND title = 'Offensive Rebounding: Angles & Second Efforts') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_rebounding, 'Offensive Rebounding: Angles & Second Efforts',
      'Offensive rebounds create extra possessions. Learn how to beat box outs, read where misses go, and know when to crash and when to get back.',
      'placeholder', 'HoopIQ', 6,
      ARRAY['Move before contact: do not let the defender put their body on you', 'Read shot angle and distance: long shots lead to long rebounds', 'Know your team rule on who crashes and who gets back'],
      'How many offensive rebounds did you get in your last game? Did you crash on shots, or were you standing and watching? Think of one time you could have gotten to the glass.',
      '[
        {"question": "What is the best way to beat a box out?", "options": ["Push the defender in the back", "Stand behind the defender", "Move before the defender can make contact, using a swim or spin move to get position", "Wait for the rebound to come to you"], "correct_index": 2, "explanation": "Once a good defender has contact, you are stuck. Moving first, with quick footwork, gets you to the ball."},
        {"question": "Decision point: A teammate shoots a three from the right wing. You are on the left block. Where should you try to position?", "options": ["Directly in front of the rim on the right side", "Behind the backboard", "Sprint back on defense immediately, every time", "On the weak side around the left block, where long misses often carry"], "correct_index": 3, "explanation": "Misses from the wing often carry to the weak side, so holding and fighting for that area is valuable."},
        {"question": "What is a tip-out?", "options": ["A quick pass after a made basket", "Tapping the ball to a teammate or open space when you cannot secure it cleanly", "A jump ball", "A technical foul"], "correct_index": 1, "explanation": "If you cannot grab it, keeping it alive with a tip to a teammate still wins the possession."},
        {"question": "Why do long shots often produce long rebounds?", "options": ["They hit the rim with more energy and bounce farther", "Long shots always miss", "The rim is softer", "They have more sidespin"], "correct_index": 0, "explanation": "Deeper shots carry more speed into the rim, so the ball tends to bounce farther away."},
        {"question": "What does crash the glass mean?", "options": ["Hit the backboard", "Break the rim", "Stop rebounding", "Aggressively go after the offensive rebound when a shot goes up"], "correct_index": 3, "explanation": "Crashing means attacking the rim area on a shot instead of watching it."},
        {"question": "Decision point: Your team rule is that guards get back on defense after a shot. You are a guard at the top of the key when a teammate shoots. What should you do?", "options": ["Crash the rim anyway", "Get back to protect against the fast break", "Stand at the top and watch", "Run to the corner"], "correct_index": 1, "explanation": "Team balance matters. Following the rule prevents easy fast-break baskets the other way."},
        {"question": "What is a second effort?", "options": ["Continuing to fight for the ball after your first jump or tip, instead of stopping", "Shooting a second free throw", "Taking a timeout", "A second foul"], "correct_index": 0, "explanation": "Many rebounds are won by the player who jumps again, not the player who jumps highest."}
      ]'::jsonb, 2);
  END IF;

  IF v_rebounding IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_rebounding AND title = 'Team Rebounding & Finishing the Defensive Possession') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_rebounding, 'Team Rebounding & Finishing the Defensive Possession',
      'A defensive possession is not over until your team has the ball. Learn how all five players share rebounding duties, guards included.',
      'placeholder', 'HoopIQ', 6,
      ARRAY['All five players box out; guards must hit and help, not leak out early', 'Help-side defenders often need to box out the nearest opponent, not their own player', 'Secure the rebound first, then outlet quickly to start transition'],
      'In your last game, did you box out on every shot, or did you leave early to run? Think of one possession where the defense did everything right and then gave up an offensive rebound.',
      '[
        {"question": "Why must guards box out too?", "options": ["Opposing guards and wings often crash long rebounds, and a missed box out gives away a second chance", "Guards get extra points for rebounds", "It is required by the rules", "Guards are usually the tallest players"], "correct_index": 0, "explanation": "Long rebounds land in guard territory. If guards do not hit someone, the offense gets extra chances."},
        {"question": "Decision point: You helped in the paint when the shot went up, and now you are far from your own player. What should you do?", "options": ["Run back out to find your own player", "Jump for the ball without making contact", "Box out the nearest opponent", "Sprint to the other end"], "correct_index": 2, "explanation": "After a rotation, box out whoever is closest. Chasing your original player leaves someone free near the rim."},
        {"question": "What is the risk of leaking out before your team secures the rebound?", "options": ["There is no risk", "It always gives you a layup", "The referee calls a foul", "Your team is a rebounder short, giving the offense a better chance at a second shot"], "correct_index": 3, "explanation": "Leaking out early trades a sure possession for a gamble. Finish the defense first."},
        {"question": "Decision point: You grab a defensive rebound in traffic. What should you do next?", "options": ["Hold the ball and wait", "Chin it, then look to outlet quickly to start the break", "Dribble into the traffic", "Throw a long pass without looking"], "correct_index": 1, "explanation": "Protect it first, then move it. A quick, safe outlet turns a stop into a transition chance."},
        {"question": "Decision point: A shot goes up and the opposing center is crashing from the weak side with nobody on them. You are the nearest defender. What is the best play?", "options": ["Stay with your own player on the perimeter", "Make contact with the crashing center to box them out", "Watch the ball", "Leak out for a fast break"], "correct_index": 1, "explanation": "An unblocked big crashing the rim is the biggest threat. The nearest defender must hit them."},
        {"question": "What does it mean to finish the defensive possession?", "options": ["Getting the stop and securing the rebound, so the opponent gets only one shot", "Scoring on offense", "Fouling at the end", "Calling a timeout"], "correct_index": 0, "explanation": "A great defensive possession is wasted if the opponent gets the offensive rebound."},
        {"question": "Which is a good team rebounding habit?", "options": ["One player rebounds while the others run", "Everyone jumps for the ball without boxing out", "Only the center boxes out", "All five players find someone to hit, then pursue the ball"], "correct_index": 3, "explanation": "Team rebounding means every player makes contact, then everyone goes after the ball."}
      ]'::jsonb, 3);
  END IF;

