  IF v_post IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_post AND title = 'Establishing Post Position: Sealing & Posting Up') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_post, 'Establishing Post Position: Sealing & Posting Up',
      'Learn how to fight for position before the catch, seal your defender, and give your passer a clear target.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Win position before the catch: work early, low, and wide', 'Seal with your hips and backside, arm bar up, and show a target hand', 'Catch with two hands, chin the ball, and feel the defender before you move'],
      'Think about your last post touch in a game or practice. Did you have to work hard to get the ball, or was the catch easy? Were you too far out or too close to the rim?',
      '[
        {"question": "When should you start fighting for post position?", "options": ["After you catch the ball", "Only after timeouts", "Before the catch, as soon as the ball is moving toward your side", "Only on free throws"], "correct_index": 2, "explanation": "Post position is won before the pass. By the time the ball arrives, the battle should already be over."},
        {"question": "What does sealing your defender mean?", "options": ["Using your body, hips, and backside to pin the defender behind or to one side of you so you can receive the pass", "Holding the defender with your hands", "Standing next to them", "Pushing them out of bounds"], "correct_index": 0, "explanation": "A good seal keeps the defender on your back or hip and opens a clear passing lane."},
        {"question": "Decision point: Your defender is fronting you, standing between you and the ball. What is the best counter?", "options": ["Keep calling for a direct pass", "Leave the post and go to the three-point line", "Stop moving", "Seal them and look for a lob over the top, or have the ball moved to a new passing angle"], "correct_index": 3, "explanation": "A fronting defender has given up the space behind them. A lob or a new angle beats the front."},
        {"question": "Why should a post player show a target hand?", "options": ["It is a rule", "It tells the passer exactly where to throw the ball, away from the defender", "It blocks the defender''s view", "It helps with free throws"], "correct_index": 1, "explanation": "A clear target away from the defender makes the entry pass safer and easier."},
        {"question": "What is a good post catching position?", "options": ["Standing straight up", "Behind the backboard", "Out near the three-point line", "Low and wide around the block or just outside the lane, with knees bent"], "correct_index": 3, "explanation": "Catching close to the rim with a strong base gives you scoring options before help arrives."},
        {"question": "Decision point: Your defender is playing behind you and you catch deep near the rim. What should you do?", "options": ["Feel where the defender is and make a quick move or finish before help arrives", "Pass back out immediately, every time", "Dribble several times", "Wait for a double team"], "correct_index": 0, "explanation": "A deep catch is a scoring chance. Be quick and decisive before the defense can send help."},
        {"question": "What should you do right after catching the ball in the post?", "options": ["Throw the ball back up the floor", "Dribble right away", "Chin the ball, feel the defender, and check whether help is coming", "Hold the ball low near your waist"], "correct_index": 2, "explanation": "Chinning protects the ball, and a quick read of the defender and help tells you whether to score or pass."}
      ]'::jsonb, 1);
  END IF;

  IF v_post IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_post AND title = 'Post Moves & Counters: Drop Steps, Hooks & Up-and-Unders') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_post, 'Post Moves & Counters: Drop Steps, Hooks & Up-and-Unders',
      'Learn a few core post moves and their counters so you can score from the block while reading how your defender is playing you.',
      'placeholder', 'HoopIQ', 8,
      ARRAY['Feel the defender: go away from the side they are playing', 'Master a few moves and one counter for each, rather than lots of moves', 'Use the drop step, hook shot, and up-and-under to create space and finish'],
      'What is your go-to move in the post? Think about a recent post touch: which side was the defender playing, and did your move go away from them? What counter do you need to practise?',
      '[
        {"question": "What is a drop step?", "options": ["Stepping backward away from the rim", "Pivoting on one foot and swinging the other foot around the defender toward the basket to seal them and finish", "A jump pass", "A defensive slide"], "correct_index": 1, "explanation": "The drop step uses your body to seal the defender while taking you straight toward the rim."},
        {"question": "Decision point: You catch on the left block with your back to the basket and feel your defender leaning on your right hip, the middle side. Which move goes away from them?", "options": ["Turn into the middle", "Hold the ball and wait", "Pass back to the wing every time", "Drop step toward the baseline"], "correct_index": 3, "explanation": "The defender is guarding the middle, so the baseline is open. Go away from the pressure."},
        {"question": "What is the main advantage of a hook shot?", "options": ["Your body shields the ball from the defender, and the high release is hard to block", "It is worth more points", "It is always a bank shot", "It requires no practice"], "correct_index": 0, "explanation": "With your shoulder between the defender and the ball, the hook is one of the hardest shots to block."},
        {"question": "Decision point: You shot fake in the post and your defender jumps. What is the best move?", "options": ["Shoot into their body while they are in the air, without any footwork", "Hold the ball until they land", "Step through past them with an up-and-under and finish", "Pass out immediately"], "correct_index": 2, "explanation": "A defender in the air cannot recover. Stepping through gives you a clear path to the rim."},
        {"question": "What does it mean to have a counter move?", "options": ["A move you only use in practice", "A move toward the scorer''s table", "A pass", "A second move that uses the defender''s reaction to your first move"], "correct_index": 3, "explanation": "Good defenders take away your first move. The counter punishes them for doing it."},
        {"question": "Decision point: You spin baseline for a layup, but a help defender rotates over from the weak side to block it. What is the best play?", "options": ["Pass to the teammate whose defender helped, often cutting or waiting on the weak side", "Force the layup", "Take extra steps", "Throw it out of bounds"], "correct_index": 0, "explanation": "The helper left someone open near the rim. A quick pass beats forcing a shot into two defenders."},
        {"question": "Why should post players learn to finish with both hands?", "options": ["It looks better", "It is a rule", "Using the hand away from the defender protects the shot on either side of the rim", "You can only use each hand once per game"], "correct_index": 2, "explanation": "Finishing with the far hand keeps the ball away from the shot blocker, whichever side you turn to."}
      ]'::jsonb, 2);
  END IF;

  IF v_post IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_post AND title = 'Passing Out of the Post & Beating Double Teams') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_post, 'Passing Out of the Post & Beating Double Teams',
      'Great post players are also great passers. Learn how to read double teams and find open shooters and cutters.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Read where the double comes from: the open player is usually the one the helper left', 'Stay strong: chin the ball, pivot, and pass before the double closes', 'Teammates relocate: shooters move to open windows and cutters dive when the post is doubled'],
      'Think about a recent post possession where you got doubled or saw help coming. Did you force a shot or find the open player? Where was the open teammate?',
      '[
        {"question": "When a double team comes to the post, where is the open player usually?", "options": ["Under the basket", "On the bench", "Near half court", "Wherever the helping defender came from"], "correct_index": 3, "explanation": "The second defender left someone. Knowing where they came from tells you where to pass."},
        {"question": "Decision point: You catch on the block and the defender guarding the wing passer drops down to double you. What is the best pass?", "options": ["A long pass to the opposite corner", "Dribble out of the double first", "Pass back out to the wing who passed you the ball, since their defender left", "Shoot over two defenders"], "correct_index": 2, "explanation": "The double came from the passer''s defender, so the passer is now open. That is the quickest, safest pass."},
        {"question": "What should you do when you sense a double team coming before you catch?", "options": ["Be ready to pass quickly, knowing where the open player will be", "Hold the ball tightly and wait", "Put the ball on the floor", "Turn toward the double and shoot"], "correct_index": 0, "explanation": "Anticipating the double lets you pass before it arrives, which is when the defense is most exposed."},
        {"question": "Why do post players pass out of a double team instead of forcing a shot?", "options": ["Post shots are not allowed", "It is faster to shoot", "Two defenders on one player means a teammate is open for a better shot", "The coach says so"], "correct_index": 2, "explanation": "A double team is an advantage for the offense if the ball moves quickly to the open player."},
        {"question": "Decision point: The double team comes from the baseline side, and your teammate on the weak side cuts to the basket. What should you do?", "options": ["Hit the cutter with a pass toward the rim, since the defense is scrambling", "Ignore the cutter and shoot", "Hold the ball until the double leaves", "Call timeout"], "correct_index": 0, "explanation": "The scrambling defense leaves the rim open. A quick pass to the cutter is a high-percentage chance."},
        {"question": "What is the risk of dribbling out of a post double team?", "options": ["There is no risk", "It always works", "It is a violation", "Defenders can reach for the ball, and it gives the defense time to recover"], "correct_index": 3, "explanation": "Dribbling in a double exposes the ball and wastes the advantage the double created."},
        {"question": "How should perimeter players move when the post is doubled?", "options": ["Stand still", "Relocate to open passing windows and be ready to shoot", "Run to the post", "Leave the court"], "correct_index": 1, "explanation": "Moving into the post player''s line of sight turns the double team into an open shot."}
      ]'::jsonb, 3);
  END IF;

  -- ---------------------------------------------------------------------------
  -- Game Situations & Clock Management
  -- ---------------------------------------------------------------------------
  IF v_situations IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_situations AND title = 'End-of-Quarter & End-of-Game Possessions') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_situations, 'End-of-Quarter & End-of-Game Possessions',
      'Learn how to manage the clock at the end of periods: when to take the last shot, when to attack early, and how to avoid giving the opponent a final possession.',
      'placeholder', 'HoopIQ', 8,
      ARRAY['Know the time and score before every late possession', 'Plan to leave little or no time for the opponent while still getting a good shot', 'Start the attack early enough to allow a second option or an offensive rebound'],
      'Think about the last close game you played. In the final minute, did you know the score, the time, and how many timeouts and fouls each team had? What would you do differently?',
      '[
        {"question": "What should you know before every late-game possession?", "options": ["Only your own points", "The referee''s name", "The score, time remaining, shot clock, and each team''s fouls and timeouts", "What you will eat after the game"], "correct_index": 2, "explanation": "Every late-game decision depends on this information. Smart players check it before the possession starts."},
        {"question": "Decision point: The game is tied and your team has the ball with about 25 seconds left, and the shot clock will not run out before the game clock. What is the usual plan?", "options": ["Run clock and start your attack with around 8 to 10 seconds left, so you get a good shot and leave little time for a response", "Shoot right away", "Pass it around and shoot from half court at the buzzer", "Call timeout immediately every time"], "correct_index": 0, "explanation": "Starting with a few seconds to spare gets a good shot and a chance at a rebound, while leaving the opponent little time."},
        {"question": "Why do teams often avoid shooting with lots of time left when the game is tied late?", "options": ["Early shots do not count", "Shooting early is a foul", "The shot clock stops", "It gives the opponent time to score on the next possession"], "correct_index": 3, "explanation": "Scoring too early hands the opponent a final possession with plenty of time to answer."},
        {"question": "Why start your final attack with a few seconds to spare rather than right at the buzzer?", "options": ["It is a rule", "It leaves time for a second option, a pass, or an offensive rebound if the first shot misses", "The clock stops", "Defenses get tired"], "correct_index": 1, "explanation": "A shot at the buzzer is the only shot. Starting a little earlier gives you a second chance."},
        {"question": "Decision point: Your team is up by 1 with 30 seconds left, and the shot clock is shorter than the game clock. You have the ball. What is the priority?", "options": ["Take the first shot you see", "Throw a risky pass to a cutter", "Hold the ball in one spot until the shot clock expires", "Take care of the ball, use the clock, and still get a good shot late in the shot clock"], "correct_index": 3, "explanation": "Protecting the ball matters most, but you still need a real shot before the shot clock expires."},
        {"question": "What is a two-for-one?", "options": ["Taking a good, quick shot near the end of a period so your team can get the ball back for the final possession", "Two free throws for one foul", "Two players guarding one", "Two timeouts in a row"], "correct_index": 0, "explanation": "With the right amount of time left, a quick good shot can earn your team an extra possession before the period ends."},
        {"question": "Decision point: Your team is down 6 with one minute left. What is the most common strategy?", "options": ["Hold the ball to run the clock", "Stop playing defense", "Look for quick, good shots, and foul if needed to stop the clock and get the ball back", "Only take half-court shots"], "correct_index": 2, "explanation": "When trailing, you need extra possessions. Score efficiently and quickly, and use fouls to stop the clock if necessary."}
      ]'::jsonb, 1);
  END IF;

  IF v_situations IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_situations AND title = 'Shot Clock Awareness & Possession Value') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_situations, 'Shot Clock Awareness & Possession Value',
      'Play with the shot clock in mind: when to be patient, when to be aggressive, and how to avoid a late-clock scramble.',
      'placeholder', 'HoopIQ', 6,
      ARRAY['Early in the clock, look for advantages; late in the clock, get the best shot available', 'Do not waste time holding the ball; early movement creates better late options', 'Know your late-clock options and get them the ball with time to act'],
      'Think about a possession in your last game that ended with a rushed shot or a shot clock violation. When did the offense stall, and what could have been done earlier?',
      '[
        {"question": "Why should an offense start its action early in the shot clock?", "options": ["It leaves time for second and third options if the first action is defended", "It makes the game more fun to watch", "It stops the clock", "It forces the defense to foul"], "correct_index": 0, "explanation": "Good defenses stop first options. Starting early leaves room for the counters that actually score."},
        {"question": "Decision point: There are 4 seconds left on the shot clock and you catch on the wing with a defender close. What is the best choice?", "options": ["Make an extra pass to the corner", "Hold the ball and hope", "Call for a screen that will take several seconds to set", "Attack immediately with a quick drive or rise up for the best shot you can get"], "correct_index": 3, "explanation": "With so little time, there is no room for another action. Be decisive and get a shot up."},
        {"question": "What is a common cause of late-shot-clock problems?", "options": ["Too much ball movement early", "Holding the ball and over-dribbling early in the possession", "Taking good shots early", "Setting screens"], "correct_index": 1, "explanation": "Time wasted early leaves the offense rushing at the end."},
        {"question": "What is a good late-clock option?", "options": ["Your least confident shooter", "A random pass", "Your team''s best creator getting the ball with enough time to make a move", "A timeout every possession"], "correct_index": 2, "explanation": "Late in the clock, put the ball in the hands of the player most able to create a decent shot."},
        {"question": "Decision point: You get a wide-open catch-and-shoot three with plenty of time on the shot clock. You are a good shooter. Should you take it?", "options": ["No, always use most of the clock", "No, only the point guard should shoot early", "Only if the coach calls your name", "Yes, a good open shot from a capable shooter is fine early in the clock"], "correct_index": 3, "explanation": "A great shot early is still a great shot. Shot quality matters more than time used."},
        {"question": "Decision point: Your offense runs its first action with about half the shot clock left, and it is well defended. What should happen next?", "options": ["Flow straight into the next action or a ball reversal instead of stopping the ball", "Hold the ball and wait for the clock to run down", "Take a contested shot right away", "Pass back to the point guard to walk it up again"], "correct_index": 0, "explanation": "Keeping the ball moving puts pressure on the defense and avoids a late-clock scramble."},
        {"question": "What does it mean to value each possession?", "options": ["Holding the ball as long as possible", "Only taking half-court shots", "Avoiding careless turnovers and bad shots, because every possession is a chance to score", "Letting the best player shoot every time"], "correct_index": 2, "explanation": "Every possession is worth points. Careless turnovers and forced shots throw those chances away."}
      ]'::jsonb, 2);
  END IF;

  IF v_situations IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_situations AND title = 'Fouls, Timeouts & Inbounds Plays') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_situations, 'Fouls, Timeouts & Inbounds Plays',
      'Understand how fouls, timeouts, and inbounds plays change the late-game picture, without getting lost in rule details that vary between levels.',
      'placeholder', 'HoopIQ', 7,
      ARRAY['Know the team foul situation, because it changes how aggressively you can defend', 'Use timeouts to set up plays and stop momentum, not just out of panic', 'On inbounds, have a plan, use screens, and give the passer a safe outlet'],
      'Think about a recent inbounds play that went wrong or a late foul that hurt your team. What was the situation, and what would a smarter choice have been?',
      '[
        {"question": "Why should defenders know how many team fouls their team has?", "options": ["It changes the scoreboard color", "It decides the final score", "It has no effect", "More fouls can send the opponent to the free-throw line, so it affects how aggressive you can be"], "correct_index": 3, "explanation": "Once your team is in the penalty, reaching and bumping become more costly."},
        {"question": "Decision point: You are inbounding under your own basket. Your first target is covered and your count is running. What should you do?", "options": ["Throw it to the covered teammate anyway", "Look to the safety outlet coming back toward the ball, or use a timeout if your team has one and it is allowed", "Throw it off a defender without looking", "Hold it and take the violation"], "correct_index": 1, "explanation": "Every inbounds play needs a safety valve. Use it, or a timeout, rather than forcing a pass into coverage."},
        {"question": "What is a smart use of a timeout?", "options": ["Stopping a big run by the opponent or setting up an important late possession", "Taking a break whenever you feel tired", "Arguing with the referee", "Ending the game early"], "correct_index": 0, "explanation": "Timeouts are valuable. Use them to reset momentum or run a specific play, and save some for the end."},
        {"question": "What should inbounds receivers do to get open?", "options": ["Stand still and wait", "All run to the same spot", "Use screens and change of pace, with at least one player coming back to the ball as a safety", "Stand behind their defender"], "correct_index": 2, "explanation": "Screens and movement create openings, and a safety outlet prevents a turnover or violation."},
        {"question": "Decision point: Your team is up by 2 with a few seconds left and the opponent is driving for a tying layup. What should you most avoid?", "options": ["Staying vertical and contesting", "Communicating the switch", "Protecting the rim with help", "Reaching in or jumping into the shooter, giving them free throws and a chance at an and-one"], "correct_index": 3, "explanation": "A foul turns a hard layup into free throws or a three-point play. Contest straight up."},
        {"question": "Why should you avoid fouling jump shooters, especially on three-point attempts?", "options": ["It gives them free throws, and possibly a four-point play, with no extra risk for them", "It is always a technical foul", "It ends the game", "It makes the shot worth less"], "correct_index": 0, "explanation": "Fouling a shooter is one of the most costly mistakes, because it gives away easy points."},
        {"question": "What is a sideline out-of-bounds play meant to do?", "options": ["Waste time", "Give the ball to the other team", "Get the ball in safely and often create a quick scoring chance with screens and cuts", "Only earn free throws"], "correct_index": 2, "explanation": "Inbounds plays are chances to use a set play while the defense is standing and watching the ball."}
      ]'::jsonb, 3);
  END IF;

  -- ---------------------------------------------------------------------------
  -- Mental Game
  -- ---------------------------------------------------------------------------
  IF v_mental IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_mental AND title = 'Confidence & Self-Talk') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_mental, 'Confidence & Self-Talk',
      'Confidence is built, not found. Learn how preparation, focusing on what you control, and helpful self-talk keep you playing freely.',
      'placeholder', 'HoopIQ', 6,
      ARRAY['Confidence comes from preparation: the reps you put in are your evidence', 'Use short, helpful self-talk cues like: Next play, or: Legs and follow through', 'Focus on what you control: effort, attitude, and decisions'],
      'Think about a moment in a recent game or session when you felt confident, and one when you did not. What were you telling yourself in each moment? Write down one self-talk cue you will use next time.',
      '[
        {"question": "Where does lasting confidence mostly come from?", "options": ["Only from scoring a lot of points", "What other people say about you", "Preparation and repetition, so you trust your skills under pressure", "Luck"], "correct_index": 2, "explanation": "Confidence built on your own work holds up better than confidence that depends on results or praise."},
        {"question": "Which of these is a helpful self-talk cue?", "options": ["Next play", "Don''t miss", "I always mess this up", "Everyone is watching"], "correct_index": 0, "explanation": "Helpful cues are short and point you to what to do next. Negative or worry-based cues add pressure."},
        {"question": "Decision point: You missed your first three shots and start thinking you should stop shooting. You are open again. What is the best mindset?", "options": ["Pass every time so you cannot miss", "Force a harder shot to make up for the misses", "Worry about what the coach is thinking", "If it is a good shot that you practise, take it with your normal routine and focus on your mechanics"], "correct_index": 3, "explanation": "Good shooters judge the shot, not the last result. A good look is still a good look after a few misses."},
        {"question": "What can you always control in a game?", "options": ["The referees and the score", "Your effort, attitude, and decisions", "Your teammates'' shots", "The crowd"], "correct_index": 1, "explanation": "Focusing on what you control keeps your energy on things that actually help you play well."},
        {"question": "How does negative self-talk usually affect performance?", "options": ["It has no effect", "It improves focus", "It makes you play more freely", "It can increase tension and hesitation, which makes skills harder to perform"], "correct_index": 3, "explanation": "Tense, hesitant players move less smoothly. Changing your self-talk helps your body stay loose."},
        {"question": "Decision point: Before a big game you feel nervous. What is the most helpful way to think about it?", "options": ["Nerves are a normal sign your body is getting ready; use your routine and breathing to channel the energy", "Nerves mean you are going to play badly", "You should try to avoid the game", "Skip warm-ups to relax"], "correct_index": 0, "explanation": "Nerves are energy. Almost every athlete feels them, and a routine helps turn them into focus."},
        {"question": "How can you build confidence during practice?", "options": ["Only practise shots you already make", "Skip hard drills", "Track small wins and progress, so you have evidence that you are improving", "Only compare yourself with the best player on the team"], "correct_index": 2, "explanation": "Seeing real progress on paper gives you proof to lean on when the game gets tough."}
      ]'::jsonb, 1);
  END IF;

  IF v_mental IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_mental AND title = 'Pre-Shot Routines & Free-Throw Focus') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_mental, 'Pre-Shot Routines & Free-Throw Focus',
      'A consistent routine calms the mind and body before a shot. Learn how to build a simple, repeatable free-throw routine and use it under pressure.',
      'placeholder', 'HoopIQ', 5,
      ARRAY['Keep the routine short and the same every time: feet, dribbles, breath, target', 'A slow breath out helps settle your body and sharpen your focus', 'Pick one focus cue for the shot and trust it'],
      'Describe your current free-throw routine. Was it the same every time in your last game or session? Write it as 3 or 4 steps and practise it exactly that way in your next session.',
      '[
        {"question": "What is the purpose of a pre-shot routine?", "options": ["To waste time", "To distract the defense", "To look cool", "To create the same calm, focused state before every shot"], "correct_index": 3, "explanation": "A routine gives your mind a familiar path to follow, so pressure has less room to creep in."},
        {"question": "What makes a good free-throw routine?", "options": ["Changing it every game", "Short, simple, and the same every time", "Very long with many steps", "Using it only in games, not in practice"], "correct_index": 1, "explanation": "Simple routines are easy to repeat under pressure, and repetition is what makes them work."},
        {"question": "How can breathing help at the free-throw line?", "options": ["A slow breath out can lower tension and settle your focus", "Holding your breath for a long time adds power", "Breathing does not matter", "Breathing fast adds energy to the shot"], "correct_index": 0, "explanation": "A slow exhale helps calm your body, which helps your shooting motion stay smooth."},
        {"question": "Decision point: You are at the line in a close game and the crowd is loud. Your mind starts thinking about missing. What should you do?", "options": ["Hurry and shoot to get it over with", "Look up at the crowd", "Step back into your routine and focus on one simple cue, like your target or follow-through", "Change your shooting form"], "correct_index": 2, "explanation": "Your routine is your anchor. Return to it and give your mind one simple job."},
        {"question": "Why should you practise your routine in practice, not just in games?", "options": ["Repetition makes the routine automatic, so it holds up under pressure", "It is required by the rules", "It saves time", "Routines only work in practice"], "correct_index": 0, "explanation": "If the routine is automatic, it runs by itself when you are nervous."},
        {"question": "Which is a good single focus cue at the free-throw line?", "options": ["Please don''t miss", "The score", "Who is watching", "A simple target or body cue, like a spot on the rim or: Legs"], "correct_index": 3, "explanation": "A positive, specific cue gives your attention a job, instead of letting it drift to results or the crowd."},
        {"question": "Decision point: You missed the first of two free throws. What is the best approach to the second?", "options": ["Change your routine to fix it", "Rush the shot", "Reset with the exact same routine and focus on your cue, treating it as a brand-new shot", "Stop using your routine"], "correct_index": 2, "explanation": "Each free throw is independent. Trust the routine you have practised instead of changing it mid-game."}
      ]'::jsonb, 2);
  END IF;

  IF v_mental IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.study_items WHERE topic_id = v_mental AND title = 'Handling Mistakes & Visualization') THEN
    INSERT INTO public.study_items (topic_id, title, description, youtube_video_id, youtube_channel, duration_minutes, key_takeaways, reflection_prompt, quiz_questions, display_order)
    VALUES (v_mental, 'Handling Mistakes & Visualization',
      'Everyone makes mistakes. Learn a quick reset routine to move to the next play, and use visualization to rehearse success before it happens.',
      'placeholder', 'HoopIQ', 6,
      ARRAY['Use a quick reset: a breath, a physical cue like a clap, and a word like: Next', 'Learn from mistakes later, on film or after the game, not in the middle of play', 'Visualize specific plays in detail, using all your senses, to prepare for games'],
      'Think about a mistake from your last game or practice. How long did it stay on your mind? What reset cue will you use next time, and what is one play you will visualize before your next session?',
      '[
        {"question": "What is a reset routine?", "options": ["A way to restart the game clock", "A quick physical and mental cue that helps you let go of a mistake and focus on the next play", "Changing teams", "Sitting on the bench"], "correct_index": 1, "explanation": "A reset routine gives you a clear signal to move on, so one mistake does not become two."},
        {"question": "Decision point: You turn the ball over and the other team scores. Your teammate is inbounding the ball to you. What is the best response?", "options": ["Argue with the referee", "Hang your head and jog", "Blame a teammate", "Use your reset cue, then focus fully on the next possession"], "correct_index": 3, "explanation": "The next play is the only one you can still affect. Reset quickly and play it well."},
        {"question": "When is the best time to analyze a mistake in detail?", "options": ["Immediately, during the next play", "Never", "Later, during a timeout, after the game, or on film", "Only if the coach yells"], "correct_index": 2, "explanation": "Thinking about the last play during the current one hurts both. Save the analysis for later."},
        {"question": "What is visualization?", "options": ["Mentally rehearsing plays and skills in detail, as if you are actually doing them", "Watching TV", "Daydreaming about the crowd", "Closing your eyes during a game"], "correct_index": 0, "explanation": "Visualization is practice in your mind. It helps your body feel familiar with the situation when it happens."},
        {"question": "What makes visualization more effective?", "options": ["Picturing only the final score", "Doing it once a season", "Imagining yourself failing", "Using clear details and senses, like the sound of the ball, the feel of the floor, and the defender in front of you"], "correct_index": 3, "explanation": "The more real it feels, the more useful it is. Detail and senses make mental reps closer to real reps."},
        {"question": "Decision point: You were subbed out after a couple of mistakes and are sitting on the bench. What is the most useful thing to do?", "options": ["Sulk and stop paying attention", "Leave the bench area", "Watch the game, notice what the defense is doing, and get ready to help the team when you go back in", "Complain to teammates"], "correct_index": 2, "explanation": "The bench is a great place to learn. Staying engaged means you go back in ready and with useful information."},
        {"question": "How can you view mistakes so they help you grow?", "options": ["As information about what to practise next", "As proof you are not good enough", "As something to hide", "As someone else''s fault"], "correct_index": 0, "explanation": "Mistakes point to what to work on. Treating them as information keeps you improving instead of doubting yourself."}
      ]'::jsonb, 3);
  END IF;
END $$;
